local config = {
  str_homestory_N23dianying_90030101_1_dialog_content = "Huff... Huff! We should be safe here. I'm spent!",
  str_homestory_N23dianying_90030101_2_dialog_content = "We should be. According to the clues from the last riddle, we're safe as long as we stay in the light.",
  str_homestory_N23dianying_90030101_3_dialog_content = "Ha... I can finally take a breather.",
  str_homestory_N23dianying_90030101_4_dialog_content = "Ha... I can finally take a breather. It's so tiring being the female lead.",
  str_homestory_N23dianying_90030101_5_dialog_content = "That guy playing the killer whose been chasing us relentlessly all this time, isn't he a little TOO into his role?!",
  str_homestory_N23dianying_90030101_6_dialog_content = "Doesn't he ever need to rest?",
  str_homestory_N23dianying_90030101_7_dialog_content = "This is the latest most popular escape room venue.",
  str_homestory_N23dianying_90030101_8_dialog_content = "To make the experience more immersive, the only staff member here is the one playing the monster.",
  str_homestory_N23dianying_90030101_9_dialog_content = "It took me quite a bit of work to get us the tickets!",
  str_homestory_N23dianying_90030101_10_dialog_content = "I appreciate that, but it's so scary and convincing that it's easy to mistake it for the real thing...",
  str_homestory_N23dianying_90030101_11_dialog_content = "Sure. But isn't he taking it a little far? Not that I'm scared.",
  str_homestory_N23dianying_90030101_12_dialog_content = "Stop overthinking it already. Enough chit-chat.",
  str_homestory_N23dianying_90030101_13_dialog_content = "Logically speaking, if we can't find new clues, we'll be forced into the next part of the story.",
  str_homestory_N23dianying_90030101_14_dialog_content = "If that happens, we won't be able to reach the real ending.",
  str_homestory_N23dianying_90030101_15_dialog_content = "You're right. Let's look around.",
  str_homestory_N23dianying_90030101_16_dialog_content = "This phantom must be purely decorative... right?",
  str_homestory_N23dianying_90030101_17_dialog_content = "They sure did a good job of creating the atmosphere.",
  str_homestory_N23dianying_90030101_18_dialog_content = "That's a jack-in-the-box, right? The thing that gives you a jump scare as soon as you open it.",
  str_homestory_N23dianying_90030101_19_dialog_content = "It feels cheap and sloppy to use this kind of thing as decor.",
  str_homestory_N23dianying_90030101_20_dialog_content = "Is that... a tombstone?",
  str_homestory_N23dianying_90030101_21_dialog_content = "Look, a hand is reaching out from the grave! Is there some kind of mechanism controlling it?",
  str_homestory_N23dianying_90030101_22_dialog_content = "But why is there a vase...?",
  str_homestory_N23dianying_90030101_23_dialog_content = "Want to give it a rub? Maybe something will come out.",
  str_homestory_N23dianying_90030101_24_dialog_content = "L-Let's not!",
  str_homestory_N23dianying_90030101_24X1_dialog_content = "What a tease, Chubb.",
  str_homestory_N23dianying_90030101_25_dialog_content = "Is that a mask of a phantom wearing a hat over there?",
  str_homestory_N23dianying_90030101_26_dialog_content = "I wonder what would happen if we put it on. Would we turn into some other creature?",
  str_homestory_N23dianying_90030101_27_dialog_content = "L-Let's not mess around with it!",
  str_homestory_N23dianying_90030101_27X1_dialog_content = "I wanna touch it, Chubb!",
  str_homestory_N23dianying_90030101_28_dialog_content = "Is this a phone?",
  str_homestory_N23dianying_90030101_29_dialog_content = "Maybe it'll suddenly ring, and when you pick up you'll hear some terrifying sound from the other side!",
  str_homestory_N23dianying_90030101_30_dialog_content = "Ugh! Let's just stay away from it.",
  str_homestory_N23dianying_90030101_30X1_dialog_content = "I'm getting really curious, Chubb.",
  str_homestory_N23dianying_90030101_31_dialog_content = "Don't be scared.",
  str_homestory_N23dianying_90030101_32_dialog_content = "The rules were clear. We're safe as long as we stay in the light.",
  str_homestory_N23dianying_90030101_33_dialog_content = "The chainsaw killer definitely won't be—",
  str_homestory_N23dianying_90030101_34_dialog_content = "Ahhhh!",
  str_homestory_N23dianying_90030101_35_dialog_content = "What's happening? Why's the light flashing?",
  str_homestory_N23dianying_90030101_35X1_dialog_content = "This is terrifying!",
  str_homestory_N23dianying_90030101_35X2_dialog_content = "Is something amazing coming up?!",
  str_homestory_N23dianying_90030101_35X3_dialog_content = "Is it about to start soon? Chubb.",
  str_homestory_N23dianying_90030101_36_dialog_content = "The door is stuck!",
  str_homestory_N23dianying_90030101_37_dialog_content = "Wait... I think there's someone there?",
  str_homestory_N23dianying_90030101_38_dialog_content = "Wait... Someone's there! Another fan stalker?",
  str_homestory_N23dianying_90030101_39_dialog_content = "Ah! You can see me?",
  str_homestory_N23dianying_90030101_40_dialog_content = "Oh? You can see me, visitor?",
  str_homestory_N23dianying_90030101_41_dialog_content = "W-Who are you?",
  str_homestory_N23dianying_90030101_42_dialog_content = "I-I'm the phantom who's trapped here.",
  str_homestory_N23dianying_90030101_43_dialog_content = "I... I am the phantom who's bound here.",
  str_homestory_N23dianying_90030101_44_dialog_content = "Phantom?",
  str_homestory_N23dianying_90030101_45_dialog_content = "Ah, please don't be afraid.",
  str_homestory_N23dianying_90030101_46_dialog_content = "Yes, but don't be afraid. I won't hurt you.",
  str_homestory_N23dianying_90030101_47_dialog_content = "I'm a good phantom. I usually stay out of sight.",
  str_homestory_N23dianying_90030101_48_dialog_content = "It must be pure destiny that we met today.",
  str_homestory_N23dianying_90030101_49_dialog_content = "It must be pure destiny that we met today... or you're losing your sanity.",
  str_homestory_N23dianying_90030101_50_dialog_content = "Oh, and no need to worry about flashing lights. The lights and doors here malfunction a lot. The staff will be here soon to fix them.",
  str_homestory_N23dianying_90030101_51_dialog_content = "Just stay calm and have some patience.",
  str_homestory_N23dianying_90030101_52_dialog_content = "Just stay calm and have some patience. Maybe I can show you a few magic tricks, you know, to help you pass the time.",
  str_homestory_N23dianying_90030101_53_dialog_content = "Thanks, but no thanks...",
  str_homestory_N23dianying_90030101_54_dialog_content = "Oh, we're playing an escape room game.",
  str_homestory_N23dianying_90030101_55_dialog_content = "Oh... by the way, we're playing an escape room game.",
  str_homestory_N23dianying_90030101_56_dialog_content = "Even if the lights did go out, the staff would fix it immediately.",
  str_homestory_N23dianying_90030101_57_dialog_content = "There's no foreseeable danger.",
  str_homestory_N23dianying_90030101_58_dialog_content = "Yeah, so why not just sit down and wait for the staff to deal with it?",
  str_homestory_N23dianying_90030101_59_dialog_content = "Yes. Would you like some black coffee? Oh, my fault, I forgot that I'm a phantom now and can't brew coffee for you.",
  str_homestory_N23dianying_90030101_60_dialog_content = "Well, let's just sit down and wait for the staff.",
  str_homestory_N23dianying_90030101_61_dialog_content = "Uhm... We'll stand. Thanks.",
  str_homestory_N23dianying_90030101_62_dialog_content = "Well, there's nothing here for a lady to sit on.",
  str_homestory_N23dianying_90030101_63_dialog_content = "You may be a phantom, but you're quite attentive.",
  str_homestory_N23dianying_90030101_64_dialog_content = "So what's your story... or you got any wish or something? Maybe we can help?",
  str_homestory_N23dianying_90030101_65_dialog_content = "Really? That's very kind of you.",
  str_homestory_N23dianying_90030101_66_dialog_content = "Really? Then thank you for your trouble.",
  str_homestory_N23dianying_90030101_67_dialog_content = "It would be great if you could remind the staff to fix things faster next time.",
  str_homestory_N23dianying_90030101_68_dialog_content = "I was trapped here for over a week before they finally opened that door.",
  str_homestory_N23dianying_90030101_69_dialog_content = "Huh? A week?",
  str_homestory_N23dianying_90030101_70_dialog_content = "Oh... I gotta go. Please take care of yourselves.",
  str_homestory_N23dianying_90030101_71_dialog_content = "Just for your information, I died here.",
  str_homestory_N23dianying_90030101_72_dialog_content = "W-Wait a minute!",
  str_homestory_N23dianying_90030101_73_dialog_content = "The phantom is... gone?",
  str_homestory_N23dianying_90030101_74_dialog_content = "That was a real phantom... not an actor.",
  str_homestory_N23dianying_90030101_75_dialog_content = "That was a real phantom... not an actor.",
  str_homestory_N23dianying_90030101_76_dialog_content = "Say, we're not gonna be trapped here for a week, are we?",
  str_homestory_N23dianying_90030101_77_dialog_content = "Could she be telling the truth? Are we gonna be trapped in here for a week?",
  str_homestory_N23dianying_90030101_78_dialog_content = "T-That's not possible! Something must've gone wrong back then...",
  str_homestory_N23dianying_90030101_79_dialog_content = "Of course they'll get to us faster this time.",
  str_homestory_N23dianying_90030101_80_dialog_content = "Hey, the light starts flashing again... Huh? It's back to normal now.",
  str_homestory_N23dianying_90030101_81_dialog_content = "See? Told you!",
  str_homestory_N23dianying_90030101_82_dialog_content = "Hm? Isn't that the phantom over there?",
  str_homestory_N23dianying_90030101_83_dialog_content = "Hey, why are you back again?",
  str_homestory_N23dianying_90030101_84_dialog_content = "Hey...?",
  str_homestory_N23dianying_90030101_85_dialog_content = "Wait! It's not the same phantom!",
  str_homestory_N23dianying_90030101_85X1_dialog_content = "What?!",
  str_homestory_N23dianying_90030101_85X2_dialog_content = "I've got goosebumps, Chubb!",
  str_homestory_N23dianying_90030101_86_dialog_content = "Find it... Go find the truth...",
  str_homestory_N23dianying_90030101_87_dialog_content = "It seems to want us to... check out that book.",
  str_homestory_N23dianying_90030101_88_dialog_content = "It wants us to check out that book. I'm familiar with the passionate and eager look in its eyes.",
  str_homestory_N23dianying_90030101_89_dialog_content = "That must be it. Excuse me, what's in the book?",
  str_homestory_N23dianying_90030101_90_dialog_content = "Find it... Go find the truth...",
  str_homestory_N23dianying_90030101_91_dialog_content = "Don't you have any other lines?",
  str_homestory_N23dianying_90030101_92_dialog_content = "Didn't I just tell you? Find it... Go find the truth!",
  str_homestory_N23dianying_90030101_93_dialog_content = "Wow! It got angry!",
  str_homestory_N23dianying_90030101_94_dialog_content = "I guess we'll have to check it.",
  str_homestory_N23dianying_90030101_95_dialog_content = "This is...!",
  str_homestory_N23dianying_90030101_96_option_content = "A journal",
  str_homestory_N23dianying_90030101_97_dialog_content = "Female lead, you open it and realize it to be a journal.",
  str_homestory_N23dianying_90030101_98_dialog_content = "XX.XX.XXXX",
  str_homestory_N23dianying_90030101_99_dialog_content = "Lady Victoria, please punish me. I so deserve it.",
  str_homestory_N23dianying_90030101_100_dialog_content = "Lady Victoria, please forgive my sins as I am a filthy monster...",
  str_homestory_N23dianying_90030101_101_dialog_content = "I tried to leave Hunting Stone on Soroz and leave by myself.",
  str_homestory_N23dianying_90030101_102_dialog_content = "But it just came back in no time!",
  str_homestory_N23dianying_90030101_103_dialog_content = "Is there any way to get rid of it? To anyone who's watching this, I'll pay you a hefty price for getting rid of it for me.",
  str_homestory_N23dianying_90030101_104_dialog_content = "Hey, no personal favors, chubb!",
  str_homestory_N23dianying_90030101_105_dialog_content = "We'd be in big trouble if anyone were to see this, chubb!",
  str_homestory_N23dianying_90030101_106_dialog_content = "I-Is this the right prop?",
  str_homestory_N23dianying_90030101_107_dialog_content = "It looks to be his own journal!",
  str_homestory_N23dianying_90030101_108_dialog_content = "It's so hard to imagine...",
  str_homestory_N23dianying_90030101_109_dialog_content = "Sigh... Feels more like a bitter ghost than a phantom.",
  str_homestory_N23dianying_90030101_110_dialog_content = "Am I the only sane person in the True Order?",
  str_homestory_N23dianying_90030101_111_dialog_content = "I'm sorry to have read your journal.",
  str_homestory_N23dianying_90030101_112_dialog_content = "No... It's my fault, really.",
  str_homestory_N23dianying_90030101_113_dialog_content = "It's my regret and salvation.",
  str_homestory_N23dianying_90030101_114_dialog_content = "Come on! You didn't have to read it just because I said so!",
  str_homestory_N23dianying_90030101_115_dialog_content = "Who wrote this stupid script!?",
  str_homestory_N23dianying_90030101_116_dialog_content = "I don't know what you mean, but... we should reshoot this after checking the props again.",
  str_homestory_N23dianying_90030101_117_option_content = "Work Log",
  str_homestory_N23dianying_90030101_118_dialog_content = "Female lead, open it and start reading it out loud.",
  str_homestory_N23dianying_90030101_119_dialog_content = "XX.XX.XXXX",
  str_homestory_N23dianying_90030101_120_dialog_content = "The equipment in the facility malfunctioned, locking the guest in the room.",
  str_homestory_N23dianying_90030101_121_dialog_content = "The staff spent quite a few days doing emergency repairs, but...",
  str_homestory_N23dianying_90030101_122_dialog_content = "Why are you reading someone else's work log?!",
  str_homestory_N23dianying_90030101_123_dialog_content = "Ahhhhh—!",
  str_homestory_N23dianying_90030101_124_dialog_content = "Why are you shouting all of a sudden!? Are you incapable of saying anything else?",
  str_homestory_N23dianying_90030101_125_dialog_content = "And you're the one who asked us to read it!",
  str_homestory_N23dianying_90030101_126_dialog_content = "It's still my diary! You can't just read it!",
  str_homestory_N23dianying_90030101_127_dialog_content = "Why would the work log be out in the open for everyone to find? How curious, chubb.",
  str_homestory_N23dianying_90030101_128_dialog_content = "Must be the props crew, right? Chubb.",
  str_homestory_N23dianying_90030101_129_dialog_content = "Stop being so unreasonable. Who the heck are you?",
  str_homestory_N23dianying_90030101_130_dialog_content = "I'm the protagonist. Only I have the right to be unreasonable! You better answer me, side character!",
  str_homestory_N23dianying_90030101_131_dialog_content = "I-I am a phantom.",
  str_homestory_N23dianying_90030101_132_dialog_content = "We knew that!",
  str_homestory_N23dianying_90030101_133_dialog_content = "Why would you know that? Have you seen one before?",
  str_homestory_N23dianying_90030101_134_dialog_content = "I'm... a phantom. Isn't it obvious?",
  str_homestory_N23dianying_90030101_135_dialog_content = "Of course!",
  str_homestory_N23dianying_90030101_136_dialog_content = "Right. So you aren't as stupid as you look.",
  str_homestory_N23dianying_90030101_137_dialog_content = "We did. Just now, right here, actually. She said she died here because the staff couldn't repair the equipment in time to save her.",
  str_homestory_N23dianying_90030101_138_dialog_content = "We sure did. Just now, right here, actually.",
  str_homestory_N23dianying_90030101_139_dialog_content = "She said she died because of some stupid repairman.",
  str_homestory_N23dianying_90030101_140_dialog_content = "Oh, how unfortunate for her.",
  str_homestory_N23dianying_90030101_141_dialog_content = "What the heck, why's she talking smack about me behind my back?",
  str_homestory_N23dianying_90030101_142_dialog_content = "That repairman was me.",
  str_homestory_N23dianying_90030101_143_dialog_content = "I was trying to pry the door open, but something went wrong, so I got caught in between and died.",
  str_homestory_N23dianying_90030101_144_dialog_content = "I was trying to pry the door open, but something went wrong, so I got caught in between and died. Stupid, isn't it?",
  str_homestory_N23dianying_90030101_145_dialog_content = "Uhm... My condolences.",
  str_homestory_N23dianying_90030101_146_dialog_content = "Well, look on the bright side. If the stupid repairman is dead already, it won't be him rescuing us.",
  str_homestory_N23dianying_90030101_147_dialog_content = "So someone else should be here soon.",
  str_homestory_N23dianying_90030101_148_dialog_content = "Save you? Why are all of you here anyway?",
  str_homestory_N23dianying_90030101_149_dialog_content = "Exploring what remains of that escape room? How leisurely.",
  str_homestory_N23dianying_90030101_150_dialog_content = "Exploring what remains of that escape room? You are quite bold, aren't you?",
  str_homestory_N23dianying_90030101_151_dialog_content = "The remains of the escape room? What do you mean by that?",
  str_homestory_N23dianying_90030101_152_dialog_content = "Exactly what it sounds like. This place's been shut down for a while.",
  str_homestory_N23dianying_90030101_153_dialog_content = "Two people died here, what makes you think it'd still be up and running?",
  str_homestory_N23dianying_90030101_154_dialog_content = "You guys better go home. I'm going to sleep now.",
  str_homestory_N23dianying_90030101_155_dialog_content = "You should go home. I'm off to find out how to get rid of the Hunting Stone.",
  str_homestory_N23dianying_90030101_156_dialog_content = "Wait... What're you saying? Does a phantom need to sleep?",
  str_homestory_N23dianying_90030101_157_dialog_content = "It's gone...",
  str_homestory_N23dianying_90030101_158_dialog_content = "What did it mean by this place being shut down?",
  str_homestory_N23dianying_90030101_159_dialog_content = "How could this place be closed? We got in here with our tickets!",
  str_homestory_N23dianying_90030101_160_dialog_content = "Actually, if you really think about it... no one was there to check our tickets, and we haven't exactly seen anyone except for that chainsaw killer.",
  str_homestory_N23dianying_90030101_161_dialog_content = "I thought you said that was for the immersion!",
  str_homestory_N23dianying_90030101_162_dialog_content = "I was just guessing!",
  str_homestory_N23dianying_90030101_163_dialog_content = "So no one is coming to our rescue? Are we really trapped here...?",
  str_homestory_N23dianying_90030101_164_dialog_content = "But that chainsaw killer... he must be a staff member, right?",
  str_homestory_N23dianying_90030101_165_dialog_content = "I don't know... I don't know who or what he's supposed to be!",
  str_homestory_N23dianying_90030101_166_dialog_content = "Hey! The light is flashing again! Is the door still stuck?",
  str_homestory_N23dianying_90030101_167_dialog_content = "This is getting old... I-I'm not scared at all!",
  str_homestory_N23dianying_90030101_168_dialog_content = "<color=#e8d9bb>Knock, knock, knock!</color>",
  str_homestory_N23dianying_90030101_169_dialog_content = "Listen! Footsteps, from the other side of the door...",
  str_homestory_N23dianying_90030101_170_dialog_content = "Footsteps? From the other side of the door...",
  str_homestory_N23dianying_90030101_171_dialog_content = "Who... could it be?",
  str_homestory_N23dianying_90030101_172_option_content = "Mysterious Scroll",
  str_homestory_N23dianying_90030101_173_dialog_content = "The female lead opens this mysterious, weirdly-shaped scroll and starts reading.",
  str_homestory_N23dianying_90030101_174_dialog_content = "Hear me!",
  str_homestory_N23dianying_90030101_175_dialog_content = "The Lord of the Endless Void.",
  str_homestory_N23dianying_90030101_176_dialog_content = "The Conqueror of Terror and Fear.",
  str_homestory_N23dianying_90030101_177_dialog_content = "The Spawn of Void and Chaos.",
  str_homestory_N23dianying_90030101_178_dialog_content = "Johnny, the Great Culinary Demon Lord!",
  str_homestory_N23dianying_90030101_179_dialog_content = "I sacrifice to you the most delicious and fresh sandworms!",
  str_homestory_N23dianying_90030101_180_dialog_content = "Your servant awaits you!",
  str_homestory_N23dianying_90030101_181_dialog_content = "...",
  str_homestory_N23dianying_90030101_182_dialog_content = "...",
  str_homestory_N23dianying_90030101_183_dialog_content = "... That's none of my business...",
  str_homestory_N23dianying_90030101_184_dialog_content = "Director! There's something obviously wrong with the props!",
  str_homestory_N23dianying_90030101_185_dialog_content = "We have a lot of room for improvement in terms of props, don't you think? Chubb.",
  str_homestory_N23dianying_90030101_186_dialog_content = "Huh? Find what? What are you talking about?",
  str_homestory_N23dianying_90030101_187_dialog_content = "Find it... Go find the truth...",
  str_homestory_N23dianying_90030101_188_dialog_content = "Didn't I just tell you? Find it... Go find the truth...",
  str_homestory_N23dianying_90030101_189_dialog_content = "But there's nothing in that direction!",
  str_homestory_N23dianying_90030101_190_dialog_content = "No? How's that possible?",
  str_homestory_N23dianying_90030101_191_dialog_content = "Can't you see it? It's where the flesh was ripped apart and the soul devoured.",
  str_homestory_N23dianying_90030101_192_dialog_content = "The place where I was supposed to put my hand-written copies of the dogma.",
  str_homestory_N23dianying_90030101_193_dialog_content = "I think there's something wrong with the props...",
  str_homestory_N23dianying_90030101_194_dialog_content = "And Nails, you weren't following your lines!",
  str_homestory_N23dianying_90030101_195_dialog_content = "I'm sorry... I shall apologize and confess with nails...",
  str_homestory_N23dianying_90030101_196_dialog_content = "Stop, stop, stop! This ain't a gory horror movie! It'll mess up the set too!",
  str_homestory_N23dianying_90030101_197_dialog_content = "I can't even begin to imagine...",
  str_homestory_N23dianying_90030101_198_dialog_content = "Put a lid on it, will you? Stop bringing shame to the True Order's name!",
  str_homestory_N23dianying_90030101_199_dialog_content = "You really can't see it? The props team really dropped the ball!",
  str_homestory_N23dianying_90030101_200_dialog_content = "Acting with imaginary props is just so unreliable!",
  str_homestory_N23dianying_90030101_201_dialog_content = "All the props and sets feel cheap. This is no way to make a quality movie!",
  str_homestory_N23dianying_90030101_202_dialog_content = "You have a point.",
  str_homestory_N23dianying_90030101_203_dialog_content = "There's definitely something wrong, especially when even Brock thinks so.",
  str_homestory_N23dianying_90030101_204_dialog_content = "Hey! What's that supposed to mean!?",
  str_homestory_N23dianying_90030101_205_dialog_content = "Anyway, we better get the props ready and reshoot this.",
  str_homestory_N23dianying_90030101_206_dialog_content = "It's alright. I'm a patient female lead. We'll come back once the set is prepared.",
  str_homestory_N23dianying_90030201_1_dialog_content = "Is this the deepest part of the legendary Dragon Cave—the Hall of Treasures...?",
  str_homestory_N23dianying_90030201_2_dialog_content = "Well, this has gotta be the legendary Frost Mirror! It can answer any question you ask of it, and has inexhaustible magic power!",
  str_homestory_N23dianying_90030201_2X1_dialog_content = "Well, the legendary Frost Mirror has gotta be here! It can answer any question you ask of it, and has inexhaustible magic power!",
  str_homestory_N23dianying_90030201_3_dialog_content = "I have no idea where that stupid mirror-guarding dragon went, but getting this was surprisingly a piece of cake.",
  str_homestory_N23dianying_90030201_3X1_dialog_content = "I have no idea where that stupid mirror-guarding dragon went, but sneaking in here was surprisingly a piece of cake.",
  str_homestory_N23dianying_90030201_4_dialog_content = "So long as we actually get it out of here... There'll be loads of people just begging to pay through the nose for it. Who knows, the king might even grant me a title and some land!",
  str_homestory_N23dianying_90030201_4X1_dialog_content = "Or I could just use its power to make a ton of money! I'd become one of the rich in no time!",
  str_homestory_N23dianying_90030201_5_dialog_content = "Hahaha... Such a rare treasure is finally in the hands of Barbatos, the greatest criminal merchant of all time!",
  str_homestory_N23dianying_90030201_6_dialog_content = "But I can't... Wait no, the line is—so I'll just help myself.",
  str_homestory_N23dianying_90030201_6X1_dialog_content = "How could she get her lines wrong? Chubb.",
  str_homestory_N23dianying_90030201_6X2_dialog_content = "You can do it, Revy!",
  str_homestory_N23dianying_90030201_6X3_dialog_content = "Their pay should be docked for saying the wrong thing, right? Chubb.",
  str_homestory_N23dianying_90030201_7_dialog_content = "Hmm? Someone's coming. But this is the Hall of Treasures, how did they...",
  str_homestory_N23dianying_90030201_7X1_dialog_content = "Hmm? I swear I've looked everywhere, but there's nothing that looks like a magic mirror.",
  str_homestory_N23dianying_90030201_8_dialog_content = "Oh, forget it, there's no time for this. I'll just hide behind the mirror first.",
  str_homestory_N23dianying_90030201_8X1_dialog_content = "Surely no one else could have already stolen the mirror...?",
  str_homestory_N23dianying_90030201_9_dialog_content = "Found it! I Found it—!!",
  str_homestory_N23dianying_90030201_9X1_dialog_content = "Found it! I Found it—!! This must be the final stage!",
  str_homestory_N23dianying_90030201_10_dialog_content = "Let me have a look. Hm... This beautiful glimmer tree...",
  str_homestory_N23dianying_90030201_10X1_dialog_content = "Let's take a look at this beautiful glimmer tree!",
  str_homestory_N23dianying_90030201_11_dialog_content = "Hmm... Such a vain Frost Dragon statue.",
  str_homestory_N23dianying_90030201_11X1_dialog_content = "There's also this impressive Frost Dragon statue!",
  str_homestory_N23dianying_90030201_14_dialog_content = "Great! It took a lot of hard work, but we finally beat the Frost Dragon and made it here!",
  str_homestory_N23dianying_90030201_14X1_dialog_content = "Great! It took a lot of hard work, but we finally beat the Frost Dragon and made it here! So where's the final reward?",
  str_homestory_N23dianying_90030201_16_dialog_content = "Huh...? Is this a bear doll? Frost Dragons like this sort of thing too?",
  str_homestory_N23dianying_90030201_16X1_dialog_content = "What's this? A bear doll? Ahaha! Do Frost Dragons really like this sort of thing too?",
  str_homestory_N23dianying_90030201_17_dialog_content = "I really can't see it...",
  str_homestory_N23dianying_90030201_17X1_dialog_content = "I just can't see it!",
  str_homestory_N23dianying_90030201_18_dialog_content = "I guess the rumors were true.",
  str_homestory_N23dianying_90030201_18X1_dialog_content = "So the rumors were true.",
  str_homestory_N23dianying_90030201_19_dialog_content = "This should be the Hall of Treasures guarded by the Frost Dragon.",
  str_homestory_N23dianying_90030201_19X1_dialog_content = "This place should be the Hall of Treasures that's guarded by the Frost Dragon!",
  str_homestory_N23dianying_90030201_22_dialog_content = "Hmm? What's this...? It looks kinda out of place.",
  str_homestory_N23dianying_90030201_22X1_dialog_content = "Oh? What the heck is this? It looks totally out of place.",
  str_homestory_N23dianying_90030201_23_dialog_content = "Though I suppose dragons are known to hoard weird things, so I guess this does make sense.",
  str_homestory_N23dianying_90030201_23X1_dialog_content = "But the Frost Dragon doesn't seem that bright. Maybe it's been misplaced.",
  str_homestory_N23dianying_90030201_27_dialog_content = "Let me see... Um, isn't this a clothing rack?",
  str_homestory_N23dianying_90030201_27X1_dialog_content = "Let me see. Huh? This is a clothing rack, isn't it?",
  str_homestory_N23dianying_90030201_28_dialog_content = "And if you look at the clothes on it, don't they seem to be the sort of thing that a character in a fairy tale might wear?",
  str_homestory_N23dianying_90030201_28X1_dialog_content = "And how come there are girls' clothes on it? Could it be that the Frost Dragon can transform into a girl?",
  str_homestory_N23dianying_90030201_37_dialog_content = "Is this really the Hall of Treasures?",
  str_homestory_N23dianying_90030201_37X1_dialog_content = "Is this really the Hall of Treasures? We didn't make a mistake?",
  str_homestory_N23dianying_90030201_38_dialog_content = "Of course it is! Didn't we go through all that trouble AND beat the Frost Dragon to make it here?!",
  str_homestory_N23dianying_90030201_38X1_dialog_content = "Of course it is! Didn't we go through all that trouble AND beat the Frost Dragon to make it here?! Plus the walkthrough said it was supposed to be here too!",
  str_homestory_N23dianying_90030201_45_dialog_content = "Let's see... is that a snowman?",
  str_homestory_N23dianying_90030201_45X1_dialog_content = "Let me see. Huh? Why the heck is there a snowman here? Reminds me of the time I made them with my comrades.",
  str_homestory_N23dianying_90030201_46_dialog_content = "It doesn't look like it'll melt. Did the Frost Dragon make it with its own power?",
  str_homestory_N23dianying_90030201_46X1_dialog_content = "It doesn't look like it'll melt. Pretty impressive.",
  str_homestory_N23dianying_90030201_63_dialog_content = "(W-What...?! These guys actually managed to beat the Frost Dragon? The one that's supposed to be able to defeat a whole army in the blink of an eye?)",
  str_homestory_N23dianying_90030201_63X1_dialog_content = "Huh?! It's that powerful?",
  str_homestory_N23dianying_90030201_63X2_dialog_content = "So strong, Chubb.",
  str_homestory_N23dianying_90030201_63X3_dialog_content = "I don't believe it, Chubb.",
  str_homestory_N23dianying_90030201_64_dialog_content = "(Should I show myself...? I could explain that I'm just a thief or a merchant or something, it'll prevent them from thinking I'm an enemy if discovered...)",
  str_homestory_N23dianying_90030201_65_dialog_content = "(It would be terrible if they mistook me for a monster and went after me...)",
  str_homestory_N23dianying_90030201_66_dialog_content = "It didn't have to be this hard.",
  str_homestory_N23dianying_90030201_67_dialog_content = "It's all because you blindly trusted some random person you met in the dungeon.",
  str_homestory_N23dianying_90030201_68_dialog_content = "That merchant said that he'd found a whole bunch of rare equipment in the dungeon, and you just rushed on over to trade with him. But it was all fake!",
  str_homestory_N23dianying_90030201_69_dialog_content = "That one incident put us in a very difficult financial position.",
  str_homestory_N23dianying_90030201_69X1_dialog_content = "That incident put us in a very difficult financial position!",
  str_homestory_N23dianying_90030201_70_dialog_content = "And now everyone is off working. Even the healer is out helping the injured bring in some money.",
  str_homestory_N23dianying_90030201_71_dialog_content = "Huh? Oh, don't worry about me! I'm happy treating others' injuries.",
  str_homestory_N23dianying_90030201_72_dialog_content = "Umm, uh... That was just a momentary lapse of judgment. I've been much more careful since!",
  str_homestory_N23dianying_90030201_72X1_dialog_content = "Oh, that was just a momentary lapse of judgment!",
  str_homestory_N23dianying_90030201_72X2_dialog_content = "I didn't expect a harmless-looking NPC to be a threat.",
  str_homestory_N23dianying_90030201_73_dialog_content = "That's not really being more careful... And after that came the thief, who claimed to be able to help us disarm the traps in the dungeon.",
  str_homestory_N23dianying_90030201_73X1_dialog_content = "Oh really? After that came the thief, who claimed to be able to help us disarm the traps in the dungeon.",
  str_homestory_N23dianying_90030201_74_dialog_content = "But you let him join us because you hated dealing with the traps, then we woke up to find all equipment missing!",
  str_homestory_N23dianying_90030201_74X1_dialog_content = "You let him join us because you hated dealing with the traps, and then we woke up to find all our equipment missing!",
  str_homestory_N23dianying_90030201_75_dialog_content = "Luckily, it was all common equipment. The advanced gear was at the blacksmith's for repairs.",
  str_homestory_N23dianying_90030201_76_dialog_content = "Otherwise we would've had to start from scratch.",
  str_homestory_N23dianying_90030201_77_dialog_content = "I know already! I won't be so naive again!",
  str_homestory_N23dianying_90030201_77X1_dialog_content = "I know already! Once bitten, twice shy!",
  str_homestory_N23dianying_90030201_78_dialog_content = "If I ever meet anyone claiming to be a robber, or a businessman, or basically anyone suspicious, I'll just deal with them right then and there!",
  str_homestory_N23dianying_90030201_79_dialog_content = "Mmhmm, that's more like it.",
  str_homestory_N23dianying_90030201_80_dialog_content = "(... If I show myself now, I'm dead meat. Best to just stay hidden.)",
  str_homestory_N23dianying_90030201_81_dialog_content = "Let's figure out how to use the magic mirror first. According to the legends, the mirror can answer any question.",
  str_homestory_N23dianying_90030201_82_dialog_content = "Looks like an ordinary mirror to me.",
  str_homestory_N23dianying_90030201_82X1_dialog_content = "Looks like an ordinary mirror to me. Do you think there's a switch or something?",
  str_homestory_N23dianying_90030201_83_dialog_content = "Well, hitting it didn't do anything. You guys have any ideas?",
  str_homestory_N23dianying_90030201_83X1_dialog_content = "Did we find any scraps of paper with relevant information on our way here? You guys got any ideas?",
  str_homestory_N23dianying_90030201_84_dialog_content = "Nope! I'm just interested in archery.",
  str_homestory_N23dianying_90030201_84X1_dialog_content = "Nope! I'm just interested in archery and wargames.",
  str_homestory_N23dianying_90030201_85_dialog_content = "Nothing here either. I'm only interested in healing methods. Other magic confuses me.",
  str_homestory_N23dianying_90030201_85X1_dialog_content = "Nothing here either. I'm just interested in honey... Um, I mean the therapeutic uses of honey.",
  str_homestory_N23dianying_90030201_86_dialog_content = "Isn't this a coincidence! I happened to be only interested in slicing and dicing monsters, but just now, my interest expanded to include the slicing and dicing of suspicious strangers.",
  str_homestory_N23dianying_90030201_87_dialog_content = "(Huh? None of them study magic?)",
  str_homestory_N23dianying_90030201_88_dialog_content = "(This could be my chance...)",
  str_homestory_N23dianying_90030201_89_dialog_content = "Huh?! Is someone hiding behind the magic mirror?",
  str_homestory_N23dianying_90030201_89X1_dialog_content = "Huh?! Is someone behind the magic mirror? A lurking enemy?",
  str_homestory_N23dianying_90030201_90_dialog_content = "Welcome, all!",
  str_homestory_N23dianying_90030201_91_dialog_content = "Brave explorers.",
  str_homestory_N23dianying_90030201_92_dialog_content = "W-Who are you? What're you doing here?",
  str_homestory_N23dianying_90030201_92X1_dialog_content = "W-Who are you? What're you doing here? Are you an enemy or some kind of hidden easter egg?",
  str_homestory_N23dianying_90030201_93_dialog_content = "No need to fear.",
  str_homestory_N23dianying_90030201_94_dialog_content = "No need to worry.",
  str_homestory_N23dianying_90030201_95_dialog_content = "I am the spirit that resides within this object, the Mirror Sylph.",
  str_homestory_N23dianying_90030201_95X1_dialog_content = "She's really getting into the role! Hahaha!",
  str_homestory_N23dianying_90030201_95X2_dialog_content = "This is embarrassing, Chubb!",
  str_homestory_N23dianying_90030201_95X3_dialog_content = "They're really in character, Chubb.",
  str_homestory_N23dianying_90030201_96_dialog_content = "The Mirror Sylph...? I don't think I've heard you mentioned in any of the legends.",
  str_homestory_N23dianying_90030201_97_dialog_content = "Quite right, quite right. But legends are just that after all. It's not like anyone ever actually retrieved the Frost Mirror.",
  str_homestory_N23dianying_90030201_97X1_dialog_content = "Quite right, quite right. But legends are just legends. No one ever actually retrieved the Frost Mirror.",
  str_homestory_N23dianying_90030201_98_dialog_content = "But why does it talk so weird?",
  str_homestory_N23dianying_90030201_98X1_dialog_content = "That tone of voice is suspicious, if you ask me.",
  str_homestory_N23dianying_90030201_99_dialog_content = "That is, ah, that's because I've been sealed in here for a long time. My magic is weak.",
  str_homestory_N23dianying_90030201_100_dialog_content = "I beg of you, take me away from here, away from the Frost Dragon! Spirit me away to a far-off, uninhabited land.",
  str_homestory_N23dianying_90030201_101_dialog_content = "(After which I'll just slip away into the night with my magic mirror. Heehee...)",
  str_homestory_N23dianying_90030201_102_dialog_content = "Oh, I see! Well, we'd better get going!",
  str_homestory_N23dianying_90030201_103_dialog_content = "Hang on a minute! What about all that \"trusting others too easily\" business? At least ask Miss Healer for her opinion first!",
  str_homestory_N23dianying_90030201_104_dialog_content = "A real mirror sylph should be able to give us a little demonstration of the mirror's power. That would be enough for them to prove their identity.",
  str_homestory_N23dianying_90030201_104X1_dialog_content = "Let me think... Oh!",
  str_homestory_N23dianying_90030201_104X2_dialog_content = "Huh? What is it?",
  str_homestory_N23dianying_90030201_104X3_dialog_content = "Time got away from me—I have to go finish an errand the Queen gave me! I'm so sorry, Director!",
  str_homestory_N23dianying_90030201_104X4_dialog_content = "Eh, it is what it is. We'll find a replacement.",
  str_homestory_N23dianying_90030201_105_dialog_content = "(... So this is the ploy they're going with. However, I'm prepared.)",
  str_homestory_N23dianying_90030201_106_dialog_content = "But of course.",
  str_homestory_N23dianying_90030201_107_dialog_content = "Please, observe—",
  str_homestory_N23dianying_90030201_108_dialog_content = "Let there be light!",
  str_homestory_N23dianying_90030201_109_dialog_content = "Magic Mirror of Frost!",
  str_homestory_N23dianying_90030201_110_dialog_content = "(Those expensive magic scrolls finally have a use.)",
  str_homestory_N23dianying_90030201_111_dialog_content = "Wow! It's actually responding!",
  str_homestory_N23dianying_90030201_112_dialog_content = "It appears you can't just pummel it with your fists like some hero protagonist. It seems to need the Mirror Sylph to work.",
  str_homestory_N23dianying_90030201_112X1_dialog_content = "Sure enough, heroic assumptions aren't gonna work. It seems we need the help of the Mirror Sylph to use it.",
  str_homestory_N23dianying_90030201_113_dialog_content = "Meh... I bet it'll work with a couple more smacks!",
  str_homestory_N23dianying_90030201_113X1_dialog_content = "Meh... I bet it'll work with a couple more good smacks! Loads of games are designed this way!",
  str_homestory_N23dianying_90030201_114_dialog_content = "I'm not sure if I can treat a shattered Magic Mirror...",
  str_homestory_N23dianying_90030201_115_dialog_content = "Never mind that for now! Go on and try out its question-answering abilities!",
  str_homestory_N23dianying_90030201_116_dialog_content = "Step right up, Miss Healer!",
  str_homestory_N23dianying_90030201_117_dialog_content = "Okay! Oh, Magic Mirror, Magic Mirror... What will be the pinnacle of my healing accomplishments?",
  str_homestory_N23dianying_90030201_118_dialog_content = "That's the way to ask, right?",
  str_homestory_N23dianying_90030201_119_dialog_content = "One moment—",
  str_homestory_N23dianying_90030201_120_dialog_content = "The answer is emerging.",
  str_homestory_N23dianying_90030201_121_dialog_content = "You will gain fame and fortune by treating a laird who falls into a slumber due to sickness.",
  str_homestory_N23dianying_90030201_122_dialog_content = "But your greatest and final feat will be curing the Demon King of narcolepsy and endowing him with infinite energy.",
  str_homestory_N23dianying_90030201_123_dialog_content = "This has the unfortunate side effect of causing him to remain eternally awake, and in his rage and surplus of power, he destroys the entire world.",
  str_homestory_N23dianying_90030201_123X1_dialog_content = "Go ahead, keep making things up.",
  str_homestory_N23dianying_90030201_123X2_dialog_content = "Are they improvising? Chubb.",
  str_homestory_N23dianying_90030201_123X3_dialog_content = "No one's gonna believe that, Chubb!",
  str_homestory_N23dianying_90030201_124_dialog_content = "...",
  str_homestory_N23dianying_90030201_125_dialog_content = "T-The Magic Mirror isn't always totally accurate, right? No need to believe every word.",
  str_homestory_N23dianying_90030201_126_dialog_content = "I'll actually... I'll actually one day be powerful enough to awaken the Demon King??",
  str_homestory_N23dianying_90030201_127_dialog_content = "Heheheh...",
  str_homestory_N23dianying_90030201_128_dialog_content = "That's not funny, Miss Healer! You're freaking me out.",
  str_homestory_N23dianying_90030201_129_dialog_content = "Don't worry about me! It's the Archer's turn!",
  str_homestory_N23dianying_90030201_130_dialog_content = "Meh, I'm not interested. I'm not into this kinda thing.",
  str_homestory_N23dianying_90030201_131_dialog_content = "Let the Hero go next.",
  str_homestory_N23dianying_90030201_132_dialog_content = "Sure! Magic Mirror, Magic Mirror, tell me now just how mighty I will be!",
  str_homestory_N23dianying_90030201_133_dialog_content = "You... You will relinquish your title as the Hero of Light, and fall for the little creatures you meet on your adventures.",
  str_homestory_N23dianying_90030201_133X1_dialog_content = "You... You will relinquish your title as the Hero of Light, and begin studying a type of giant robot called a Magimech.",
  str_homestory_N23dianying_90030201_134_dialog_content = "You will then work with them to take down all your Gym Leader enemies, one by one.",
  str_homestory_N23dianying_90030201_134X1_dialog_content = "But those robots, initially created to protect people, will become self-aware and start attacking people instead.",
  str_homestory_N23dianying_90030201_135_dialog_content = "But you will... never become Champion, and eventually perish in despondent ignominy.",
  str_homestory_N23dianying_90030201_135X1_dialog_content = "And you'll embark on a mission with your only robot friend, to discover the truth behind the Magimech insurrection.",
  str_homestory_N23dianying_90030201_135A1_dialog_content = "It's getting more and more ridiculous, Chubb.",
  str_homestory_N23dianying_90030201_135A2_dialog_content = "Doesn't that sound familiar?",
  str_homestory_N23dianying_90030201_135A3_dialog_content = "It's... alluring, in a sort of way?",
  str_homestory_N23dianying_90030201_136_dialog_content = "How is that possible...",
  str_homestory_N23dianying_90030201_137_dialog_content = "You nonsensical Magic Mirror! How dare you thus slander my beloved Hero!",
  str_homestory_N23dianying_90030201_137X1_dialog_content = "You just keep spouting nonsense, Mirror! How dare you slander our mighty Hero!!",
  str_homestory_N23dianying_90030201_138_dialog_content = "Huh? Wait! Hang on a minute!",
  str_homestory_N23dianying_90030201_139_dialog_content = "So THAT'S your relationship—!",
  str_homestory_N23dianying_90030201_139X1_dialog_content = "Chill out!",
  str_homestory_N23dianying_90030201_140_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  str_homestory_N23dianying_90030201_141_dialog_content = "Hey, stop attacking the mirror! If you damage the Magic Mirror, the Sylph could be injured, or even killed!",
  str_homestory_N23dianying_90030201_142_dialog_content = "Look at its pained expression!",
  str_homestory_N23dianying_90030201_143_dialog_content = "Pained... expression?",
  str_homestory_N23dianying_90030201_144_option_content = "Collapse",
  str_homestory_N23dianying_90030201_145_dialog_content = "Fall, Barbatos! \"Make a pained noise and collapse!\"",
  str_homestory_N23dianying_90030201_146_dialog_content = "Ohhh...",
  str_homestory_N23dianying_90030201_147_dialog_content = "... Oh! Such agony!",
  str_homestory_N23dianying_90030201_148_dialog_content = "I am injured—",
  str_homestory_N23dianying_90030201_149_dialog_content = "I'm sorry... I was a little too impulsive...",
  str_homestory_N23dianying_90030201_149X1_dialog_content = "I'm sorry... These are the follies of youth.",
  str_homestory_N23dianying_90030201_150_dialog_content = "Might I trouble you to try, Miss Healer?",
  str_homestory_N23dianying_90030201_151_dialog_content = "I'll give it a shot... If only to stir the pot a little! I am, after all, the one who is destined to treat even a demon king!",
  str_homestory_N23dianying_90030201_152_dialog_content = "You're not gonna let anyone forget that any time soon, are you?",
  str_homestory_N23dianying_90030201_153_dialog_content = "Sigh, it's supposed to be a magic mirror. How does it break so easily?",
  str_homestory_N23dianying_90030201_154_dialog_content = "What shoddy craftsmanship.",
  str_homestory_N23dianying_90030201_155_dialog_content = "I-I sense healing power.",
  str_homestory_N23dianying_90030201_156_dialog_content = "I, the Sylph of the Mirror, am restored!",
  str_homestory_N23dianying_90030201_157_dialog_content = "Great! And, uh, our apologies.",
  str_homestory_N23dianying_90030201_157X1_dialog_content = "Great! And, uh, sorry about that.",
  str_homestory_N23dianying_90030201_158_dialog_content = "Sometimes the Archer is even more impetuous than me. But apart from this little flaw, she has a good heart.",
  str_homestory_N23dianying_90030201_159_dialog_content = "Since when did you two...",
  str_homestory_N23dianying_90030201_160_dialog_content = "Hahahahaha—",
  str_homestory_N23dianying_90030201_161_dialog_content = "Is that coming from outside?!",
  str_homestory_N23dianying_90030201_162_dialog_content = "It's the Frost Dragon!",
  str_homestory_N23dianying_90030201_163_dialog_content = "Imbeciles! Did you really think you could kill me?",
  str_homestory_N23dianying_90030201_164_dialog_content = "You've missed your chance to defeat me, and now I'm leaving—and taking the Frost Mirror with me!",
  str_homestory_N23dianying_90030201_165_dialog_content = "Rue your stupidity for the rest of your lives! Hahahaha—",
  str_homestory_N23dianying_90030201_166_dialog_content = "...",
  str_homestory_N23dianying_90030201_167_dialog_content = "...",
  str_homestory_N23dianying_90030201_168_dialog_content = "...",
  str_homestory_N23dianying_90030201_169_dialog_content = "The heck is that dumb dragon saying?",
  str_homestory_N23dianying_90030201_170_dialog_content = "Hasn't it noticed that we've got the Frost Dragon now?",
  str_homestory_N23dianying_90030201_170X1_dialog_content = "What a big buffoon! WE'VE got the Frost Mirror, hahaha!",
  str_homestory_N23dianying_90030201_171_dialog_content = "But now that we know the Frost Dragon is after the mirror, we've got to be on our guard, and keep an eye on it at all times.",
  str_homestory_N23dianying_90030201_172_dialog_content = "Don't worry. We'll protect you.",
  str_homestory_N23dianying_90030201_173_dialog_content = "... Yes, yes. Fine. You're totally right.",
  str_homestory_N23dianying_90030201_174_dialog_content = "Really, I'm very grateful to you.",
  str_homestory_N23dianying_90030201_175_option_content = "Sense something's not quite right",
  str_homestory_N23dianying_90030201_176_dialog_content = "Archer, you suddenly sense that something is amiss. \"This character is really suspicious.\"",
  str_homestory_N23dianying_90030201_177_dialog_content = "Even though the mirror where you supposedly live was clearly attacked, you didn't seem to react. Isn't that odd?",
  str_homestory_N23dianying_90030201_177X1_dialog_content = "Even though the mirror where you supposedly live was clearly attacked, you didn't seem to react. That's really rather odd.",
  str_homestory_N23dianying_90030201_178_dialog_content = "What? Are you saying that this character...",
  str_homestory_N23dianying_90030201_178X1_dialog_content = "What? You mean—are you saying that this isn't any sort of easter egg at all?",
  str_homestory_N23dianying_90030201_179_dialog_content = "Wait, just wait a minute! I can explain—I'm in pain, so much pain that I think I'm gonna pass out!",
  str_homestory_N23dianying_90030201_180_dialog_content = "I can explain! Please, just listen.",
  str_homestory_N23dianying_90030201_181_dialog_content = "Hahahahaha—",
  str_homestory_N23dianying_90030201_182_dialog_content = "Is that coming from outside?!",
  str_homestory_N23dianying_90030201_183_dialog_content = "It's the Frost Dragon!",
  str_homestory_N23dianying_90030201_184_dialog_content = "Imbeciles! Did you really think you could kill me?",
  str_homestory_N23dianying_90030201_185_dialog_content = "You've missed your chance to defeat me, and now I'm leaving—and taking the Frost Mirror with me!",
  str_homestory_N23dianying_90030201_186_dialog_content = "Rue your stupidity for the rest of your lives! Hahahaha—",
  str_homestory_N23dianying_90030201_187_dialog_content = "We won't let you get away—",
  str_homestory_N23dianying_90030201_188_option_content = "Sudden realization",
  str_homestory_N23dianying_90030201_189_dialog_content = "Hero, you suddenly realize something vital. \"The sword is gone.\"",
  str_homestory_N23dianying_90030201_190_dialog_content = "Hold up, forget about that for a second. Is it just me or is the sword missing?",
  str_homestory_N23dianying_90030201_191_dialog_content = "No way... It can't still be stuck in the Frost Dragon's head, can it?",
  str_homestory_N23dianying_90030201_192_dialog_content = "Quick, let's go back and search for it! We're in big trouble if the Hero loses the sword!",
  str_homestory_N23dianying_90030201_193_dialog_content = "Oh? Erm... Do come again?",
  str_homestory_N23dianying_90030201_194_dialog_content = "Huh? Who's this?",
  str_homestory_N23dianying_90030201_194X1_dialog_content = "Huh? Who's this? A background NPC?",
  str_homestory_N23dianying_90030201_195_dialog_content = "Forget about her. We need to look for the mirror.",
  str_homestory_N23dianying_90030201_195X1_dialog_content = "Forget about her. We need to look for the mirror. I still have things I need to do afterward.",
  str_homestory_N23dianying_90030201_196_dialog_content = "Hmm?",
  str_homestory_N23dianying_90030201_197_dialog_content = "What?",
  str_homestory_N23dianying_90030201_198_dialog_content = "How come there's no sign of the Magic Mirror?",
  str_homestory_N23dianying_90030201_198X1_dialog_content = "How come there's no sign of the Magic Mirror? Have we not yet ticked some arbitrary box??",
  str_homestory_N23dianying_90030201_199_dialog_content = "You think this one stole it?",
  str_homestory_N23dianying_90030201_200_dialog_content = "What?! I was just about to ask you that.",
  str_homestory_N23dianying_90030201_201_dialog_content = "It wasn't fun sneaking in here, and I had to have that mirror to become the richest merchant in the world.",
  str_homestory_N23dianying_90030201_202_dialog_content = "Sneaking in? You don't suppose—is this person some kind of thief?",
  str_homestory_N23dianying_90030201_203_dialog_content = "That's really quite triggering.",
  str_homestory_N23dianying_90030201_203X1_dialog_content = "That brings back some really nasty memories. I've got to teach you a lesson.",
  str_homestory_N23dianying_90030201_204_dialog_content = "Hahahahaha—",
  str_homestory_N23dianying_90030201_205_dialog_content = "Is that coming from outside?!",
  str_homestory_N23dianying_90030201_206_dialog_content = "It's the Frost Dragon!",
  str_homestory_N23dianying_90030201_207_dialog_content = "Imbeciles! Did you really think you could defeat me?",
  str_homestory_N23dianying_90030201_208_dialog_content = "Now, I'm leaving—and I'm taking the Frost Mirror with me! Another thing... This place is going to collapse any second now, so rue your stupidity for the rest of your short lives! Hahahaha—",
  str_homestory_N23dianying_90030201_209_dialog_content = "Drat, the dragon got away.",
  str_homestory_N23dianying_90030201_210_dialog_content = "Go after it, now!",
  str_homestory_N23dianying_90030201_210X1_dialog_content = "Hurry after it, everyone! I've gotta go finish the errand that the Queen tasked me with!",
  str_homestory_N23dianying_90030201_211_dialog_content = "Huh? Hey! Wait for me!",
  str_homestory_N23dianying_90030201_211X1_dialog_content = "The ending was too rushed! Chubb!",
  str_homestory_N23dianying_90030201_212_dialog_content = "I can't tell if it's just your personality or whether it was your phenomenal acting, but collapsing like that was a stroke of genius, Chubb.",
  str_homestory_N23dianying_90030201_213_dialog_content = "Hey, it took that long to figure out that something was odd? That's a bit of an abrupt plot twist, Chubb!",
  str_homestory_N23dianying_90030201_214_dialog_content = "Why don't you explain it? Go on!",
  str_homestory_N23dianying_90030201_215_dialog_content = "Well, in most films and television shows, the more you want to know, the more they ramp up the suspense, Chubb.",
  str_homestory_N23dianying_90030201_216_dialog_content = "The Frost Dragon has quite possibly already flown away with it!",
  str_homestory_N23dianying_90030201_217_dialog_content = "But there isn't even a sword prop, right? So what is even going on with this story right now, Chubb?",
  str_homestory_N23dianying_90030301_1_dialog_content = "Phew! It may have taken two days, but at least everything is coming together.",
  str_homestory_N23dianying_90030301_2_dialog_content = "Those thugs are crazy, destroying such an artistic place.",
  str_homestory_N23dianying_90030301_3_dialog_content = "But luckily, the piano escaped relatively unscathed...",
  str_homestory_N23dianying_90030301_3X1_dialog_content = "It looks expensive, Chubb.",
  str_homestory_N23dianying_90030301_4_dialog_content = "But luckily, I managed to use this chance to persuade the boss to swap the piano for a stage.",
  str_homestory_N23dianying_90030301_5_dialog_content = "Now, I can sing to my heart's content...",
  str_homestory_N23dianying_90030301_5X1_dialog_content = "I want to turn down the volume, Chubb...",
  str_homestory_N23dianying_90030301_6_dialog_content = "I can't believe the boss is so stingy.",
  str_homestory_N23dianying_90030301_7_dialog_content = "Unwilling to pay for piano repairs after it was damaged.",
  str_homestory_N23dianying_90030301_8_dialog_content = "AND sending me off to the old warehouse for random decor.",
  str_homestory_N23dianying_90030301_8X1_dialog_content = "What is this?",
  str_homestory_N23dianying_90030301_9_dialog_content = "<color=#e8d9bb>Ding—</color>",
  str_homestory_N23dianying_90030301_10_dialog_content = "I'm sorry, but we're closed—",
  str_homestory_N23dianying_90030301_11_dialog_content = "Huh? You again?!",
  str_homestory_N23dianying_90030301_12_dialog_content = "Now, now. That's no way to welcome your patrons, Mr. Bartender.",
  str_homestory_N23dianying_90030301_12X1_dialog_content = "We meet again, bartender boy.",
  str_homestory_N23dianying_90030301_13_dialog_content = "I have some pressing matters to discuss with an old friend today, so two glasses of Umbraton Encounter, if you'd be so kind.",
  str_homestory_N23dianying_90030301_13X1_dialog_content = "I've brought an old friend here to discuss business today, so two glasses of the Rediesel Special, please.",
  str_homestory_N23dianying_90030301_14_dialog_content = "We're not serving drinks right now.",
  str_homestory_N23dianying_90030301_15_dialog_content = "You can thank your crazy lackeys for that, coming in here a couple of days ago and smashing the place up!",
  str_homestory_N23dianying_90030301_16_dialog_content = "Oh, that's such a shame. It appears I won't be able to offer you a drink on this occasion.",
  str_homestory_N23dianying_90030301_16X1_dialog_content = "Oh, that's right. There was that... incident.",
  str_homestory_N23dianying_90030301_17_dialog_content = "You were there when it happened! Don't play innocent with me!",
  str_homestory_N23dianying_90030301_17X1_dialog_content = "Shall we try somewhere else?",
  str_homestory_N23dianying_90030301_18_dialog_content = "It's fine. We're only going over the contract anyway. Let's just get it done.",
  str_homestory_N23dianying_90030301_19_dialog_content = "By the way, could you ask the bartender to change the music to something a little more... refined?",
  str_homestory_N23dianying_90030301_20_dialog_content = "Your choice of music leaves a lot to be desired.",
  str_homestory_N23dianying_90030301_21_dialog_content = "What did you say?!",
  str_homestory_N23dianying_90030301_22_dialog_content = "This whole place needs a makeover, actually.",
  str_homestory_N23dianying_90030301_23_dialog_content = "What did you say?!",
  str_homestory_N23dianying_90030301_24_dialog_content = "I've got your guys fighting in here to thank for that too.",
  str_homestory_N23dianying_90030301_25_dialog_content = "They ruined all my decorations and even smashed the furniture!",
  str_homestory_N23dianying_90030301_26_dialog_content = "Fine. Let me get back to you about that a bit later.",
  str_homestory_N23dianying_90030301_27_dialog_content = "The decor here is a little... Well, it's pretty bad.",
  str_homestory_N23dianying_90030301_28_dialog_content = "I don't want to stay here a second longer than absolutely necessary.",
  str_homestory_N23dianying_90030301_29_dialog_content = "Just ask the bartender to change the record, please.",
  str_homestory_N23dianying_90030301_29X1_dialog_content = "Hahaha! Please, don't mind my friend. This is just how he speaks.",
  str_homestory_N23dianying_90030301_30_dialog_content = "We're also good friends with the boss here. I'm sure he won't mind.",
  str_homestory_N23dianying_90030301_30X1_dialog_content = "I'm good friends with your boss. He won't say anything if I take up a tiny bit of space here.",
  str_homestory_N23dianying_90030301_30X2_dialog_content = "I'll explain it all to him later on. You just hop along and change the music.",
  str_homestory_N23dianying_90030301_31_dialog_content = "Er... B-Boss?",
  str_homestory_N23dianying_90030301_32_dialog_content = "... Fine. I got it.",
  str_homestory_N23dianying_90030301_33_dialog_content = "Drat. Using my own boss to threaten me.",
  str_homestory_N23dianying_90030301_34_dialog_content = "This place will be nothing but a gang hangout at this rate.",
  str_homestory_N23dianying_90030301_35_dialog_content = "I've got to think of a way to stop them from ever wanting to set foot here again.",
  str_homestory_N23dianying_90030301_36_dialog_content = "I know! Seeing as this most elegant gentleman likes being surrounded by elegance, I have just the record—",
  str_homestory_N23dianying_90030301_37_dialog_content = "I'm sorry, this isn't what we agreed. I can't—",
  str_homestory_N23dianying_90030301_38_dialog_content = "Huh? What's gotten into the bartender? This music—",
  str_homestory_N23dianying_90030301_38X1_dialog_content = "I'm all fired up, Chubb.",
  str_homestory_N23dianying_90030301_39_dialog_content = "I'll get him to turn it off.",
  str_homestory_N23dianying_90030301_39X1_dialog_content = "Wow, the kid actually played something I like.",
  str_homestory_N23dianying_90030301_39X2_dialog_content = "But it might be a little loud for you. I'll get him to turn it off.",
  str_homestory_N23dianying_90030301_40_dialog_content = "It's fine.",
  str_homestory_N23dianying_90030301_41_dialog_content = "The melody and rhythm... This reminds me of when we used to perform together on tour.",
  str_homestory_N23dianying_90030301_42_dialog_content = "Are we gonna see flashbacks now, Chubb?!",
  str_homestory_N23dianying_90030301_43_dialog_content = "So you do remember those days.",
  str_homestory_N23dianying_90030301_44_dialog_content = "I know we set off on divergent paths over the years, as we took on different responsibilities.",
  str_homestory_N23dianying_90030301_45_dialog_content = "And I'm well aware of our conflicting positions, yet I do still get feel a bit nostalgic.",
  str_homestory_N23dianying_90030301_46_dialog_content = "As do I.",
  str_homestory_N23dianying_90030301_47_dialog_content = "... You know what? Let me go back and try to get things moving with the contract.",
  str_homestory_N23dianying_90030301_47X1_dialog_content = "... And the times that your people robbed our cargo.",
  str_homestory_N23dianying_90030301_47X2_dialog_content = "Let's not forget the time that the Shadowlord sent me after you, and I chased you through the Rediesel Desert for three full days and nights!",
  str_homestory_N23dianying_90030301_47X3_dialog_content = "Hey, come on! Aren't we meant to be making a movie? What's with the seriousness all of a sudden?",
  str_homestory_N23dianying_90030301_47X4_dialog_content = "... Sorry. I just see red whenever I have to look at his face.",
  str_homestory_N23dianying_90030301_47X5_dialog_content = "What's the line?",
  str_homestory_N23dianying_90030301_47X6_dialog_content = "Why wasn't this part cut, Chubb?!",
  str_homestory_N23dianying_90030301_47X7_dialog_content = "Oh yeah, so how about I go back and try to get things moving with the contract.",
  str_homestory_N23dianying_90030301_48_dialog_content = "See it as helping an old friend out.",
  str_homestory_N23dianying_90030301_49_dialog_content = "That easy, Chubb?",
  str_homestory_N23dianying_90030301_50_dialog_content = "I'd appreciate that.",
  str_homestory_N23dianying_90030301_51_dialog_content = "Wow, I never knew you were so adept at reading the room! We have you to thank for the success of these negotiations!",
  str_homestory_N23dianying_90030301_52_dialog_content = "You must've known about our former band, the Rockin' Dragons, before choosing that record, right?",
  str_homestory_N23dianying_90030301_52X1_dialog_content = "Oh, really? Thank you so much!",
  str_homestory_N23dianying_90030301_52X2_dialog_content = "Wow, I never knew you were so adept at reading the room! We have you to thank for the success of these negotiations!",
  str_homestory_N23dianying_90030301_52X3_dialog_content = "You must've known about our former band, the Rockin' Dragons, before choosing that record, right?",
  str_homestory_N23dianying_90030301_53_dialog_content = "Chu! What a huge misunderstanding, Chubb!",
  str_homestory_N23dianying_90030301_54_dialog_content = "I'm not—",
  str_homestory_N23dianying_90030301_55_dialog_content = "Seeing as you've proven yourself so reliable, I have another request to ask of you.",
  str_homestory_N23dianying_90030301_56_dialog_content = "I have here a most confidential, extremely important message. An intermediary will be along later to collect it.",
  str_homestory_N23dianying_90030301_56X1_dialog_content = "Hmm, it's obvious why the boss chose you to manage this place. Good work!",
  str_homestory_N23dianying_90030301_56X2_dialog_content = "Since you've proven yourself so reliable, I have another request to ask of you.",
  str_homestory_N23dianying_90030301_56X3_dialog_content = "I have here a most confidential, extremely important message. An intermediary will be along later to collect it.",
  str_homestory_N23dianying_90030301_57_dialog_content = "Hang on, I don't—",
  str_homestory_N23dianying_90030301_58_dialog_content = "Don't you worry! It's really very simple.",
  str_homestory_N23dianying_90030301_59_dialog_content = "The contact will use the code word \"Beauty Under the Moon.\" Just hand over the letter when you hear that.",
  str_homestory_N23dianying_90030301_60_dialog_content = "I have other business to tend to, so I'll take my leave.",
  str_homestory_N23dianying_90030301_60X1_dialog_content = "Don't you worry! It's really very simple.",
  str_homestory_N23dianying_90030301_60X2_dialog_content = "The contact will use the code word \"Beauty Under the Moon.\" Just hand over the letter when you hear that.",
  str_homestory_N23dianying_90030301_60X3_dialog_content = "I still have very important matters to attend to, so you know... gotta go.",
  str_homestory_N23dianying_90030301_61_dialog_content = "Hey! I haven't finished!",
  str_homestory_N23dianying_90030301_62_dialog_content = "Let people finish, Chubb!",
  str_homestory_N23dianying_90030301_63_dialog_content = "Seriously, every single one of these guys...",
  str_homestory_N23dianying_90030301_64_dialog_content = "<color=#e8d9bb>Ding—</color>",
  str_homestory_N23dianying_90030301_65_dialog_content = "Now who is it?! Don't they see the \"CLOSED\" sign on the door?",
  str_homestory_N23dianying_90030301_66_dialog_content = "Pardon the interruption, but I'm a sheriff here about the fight that broke out here a few days ago.",
  str_homestory_N23dianying_90030301_66X1_dialog_content = "Hello, I'm a sheriff, here about the fight that broke out here a few days ago.",
  str_homestory_N23dianying_90030301_67_dialog_content = "Is the owner around?",
  str_homestory_N23dianying_90030301_67X1_dialog_content = "Is the owner around?",
  str_homestory_N23dianying_90030301_68_dialog_content = "You're a sheriff? Perfect timing!",
  str_homestory_N23dianying_90030301_69_dialog_content = "I'm the bartender here, and I was an eyewitness to a criminal discussion just now. They even gave me a confidential letter.",
  str_homestory_N23dianying_90030301_70_dialog_content = "I'll tell you everything I know as long as you can stop those thugs from ever stepping foot in here again!",
  str_homestory_N23dianying_90030301_71_dialog_content = "A confidential gang letter?",
  str_homestory_N23dianying_90030301_71X1_dialog_content = "A confidential gang letter?",
  str_homestory_N23dianying_90030301_71X2_dialog_content = "That's right. If you go after them now, the ones who gave me the letter can't have gone far.",
  str_homestory_N23dianying_90030301_72_dialog_content = "You've really been a lot of help. Thank you for your cooperation, bartender.",
  str_homestory_N23dianying_90030301_73_dialog_content = "Once I confirm the situation, I'll guarantee the safety of this place.",
  str_homestory_N23dianying_90030301_74_dialog_content = "Well, get on with it then!",
  str_homestory_N23dianying_90030301_74X1_dialog_content = "I'll need to see what the letter says before I can judge the veracity of your information.",
  str_homestory_N23dianying_90030301_74X2_dialog_content = "After all, I cannot understand why they would entrust such an important item to you.",
  str_homestory_N23dianying_90030301_74X3_dialog_content = "Alright then, go ahead.",
  str_homestory_N23dianying_90030301_75_dialog_content = "\"My dearest Moon Maiden,\"",
  str_homestory_N23dianying_90030301_76_dialog_content = "\"I both appreciate your sincere enthusiasm and admire your courageous candor.\"",
  str_homestory_N23dianying_90030301_77_dialog_content = "\"But, most apologies, I do not feel the same way\"...",
  str_homestory_N23dianying_90030301_78_dialog_content = "It's a love letter, Chubb!",
  str_homestory_N23dianying_90030301_79_dialog_content = "What're you up to?",
  str_homestory_N23dianying_90030301_80_dialog_content = "Is this... a letter for me?",
  str_homestory_N23dianying_90030301_81_dialog_content = "Uh, this, this is...",
  str_homestory_N23dianying_90030301_82_dialog_content = "\"Beauty Under the Moon\" is my pseudonym.",
  str_homestory_N23dianying_90030301_83_dialog_content = "This was addressed to me, correct?",
  str_homestory_N23dianying_90030301_84_dialog_content = "Y-Yeah.",
  str_homestory_N23dianying_90030301_85_dialog_content = "I overheard you say that he's unable to return my feelings...",
  str_homestory_N23dianying_90030301_86_dialog_content = "At the end of the day, I still couldn't make it happen.",
  str_homestory_N23dianying_90030301_87_dialog_content = "Hey! Why are you touching our record player?!",
  str_homestory_N23dianying_90030301_87X1_dialog_content = "Pffffft—",
  str_homestory_N23dianying_90030301_87X2_dialog_content = "Ha ha ha!",
  str_homestory_N23dianying_90030301_87X3_dialog_content = "Charon, calm down! Chubb.",
  str_homestory_N23dianying_90030301_88_dialog_content = "I met him a month ago, under a full moon.",
  str_homestory_N23dianying_90030301_89_dialog_content = "I was hiding from some thugs at the time, and he rescued me.",
  str_homestory_N23dianying_90030301_90_dialog_content = "Er... Why is she telling us this?",
  str_homestory_N23dianying_90030301_91_dialog_content = "I asked around everywhere in town, before I finally found out who he was.",
  str_homestory_N23dianying_90030301_92_dialog_content = "But I was deluded if I thought that a man of his stature could fall for someone like me.",
  str_homestory_N23dianying_90030301_93_dialog_content = "Is that why you chose to write him a letter using a pen name?",
  str_homestory_N23dianying_90030301_93X1_dialog_content = "Is that why you chose to write him a letter using a pen name?",
  str_homestory_N23dianying_90030301_94_dialog_content = "Yes... Because I thought that, whatever happened, I would not let myself have any regrets.",
  str_homestory_N23dianying_90030301_95_dialog_content = "But it turns out that some chasms are just too wide to cross with bravery alone.",
  str_homestory_N23dianying_90030301_95X1_dialog_content = "It's admirable for a lady to have such courage.",
  str_homestory_N23dianying_90030301_95X2_dialog_content = "It's his loss to reject such an elegant lady.",
  str_homestory_N23dianying_90030301_96_dialog_content = "I can certainly understand how you feel, Moon Maiden.",
  str_homestory_N23dianying_90030301_97_dialog_content = "Are they commiserating right now?!",
  str_homestory_N23dianying_90030301_98_dialog_content = "The fact you had the courage to do that in the first place is admirable.",
  str_homestory_N23dianying_90030301_99_dialog_content = "I think you shouldn't give up on your feelings quite so fast. Help him understand you.",
  str_homestory_N23dianying_90030301_100_dialog_content = "Don't just give up at the first hurdle.",
  str_homestory_N23dianying_90030301_101_dialog_content = "Thank you... You're the first person to tell me that.",
  str_homestory_N23dianying_90030301_101X1_dialog_content = "I'm the sheriff around here, so if you need anything in the future, you be sure to come and find me.",
  str_homestory_N23dianying_90030301_101X2_dialog_content = "And... I apologize for reading your letter. I shouldn't have done that.",
  str_homestory_N23dianying_90030301_101X3_dialog_content = "I trust you. I believe you had only good intentions.",
  str_homestory_N23dianying_90030301_101X4_dialog_content = "Thank you for your kindness and understanding.",
  str_homestory_N23dianying_90030301_101X5_dialog_content = "Now... as for you, Mr. Charon.",
  str_homestory_N23dianying_90030301_101X6_dialog_content = "Uh... Yes?",
  str_homestory_N23dianying_90030301_101X7_dialog_content = "Aren't I supposed to be the bartender?",
  str_homestory_N23dianying_90030301_101X8_dialog_content = "There's no way I can forgive you for prying into a young lady's most personal affairs.",
  str_homestory_N23dianying_90030301_101X9_dialog_content = "Such reprehensible behavior must be punished by the law and condemned by common morality!",
  str_homestory_N23dianying_90030301_101X10_dialog_content = "...!",
  str_homestory_N23dianying_90030301_101X11_dialog_content = "Tone it down, Pittman!",
  str_homestory_N23dianying_90030301_101X12_dialog_content = "He's getting a little too into character, Chubb!",
  str_homestory_N23dianying_90030301_101X13_dialog_content = "Wait, wait, wait!",
  str_homestory_N23dianying_90030301_101X14_dialog_content = "Aren't we filming a movie here? It's what the script says!",
  str_homestory_N23dianying_90030301_101X15_dialog_content = "It's not like I wanted to read it!",
  str_homestory_N23dianying_90030301_101X16_dialog_content = "Hmph, still trying to make excuses.",
  str_homestory_N23dianying_90030301_101X17_dialog_content = "Accept your punishment!",
  str_homestory_N23dianying_90030301_101X18_dialog_content = "Wait!",
  str_homestory_N23dianying_90030301_101X19_dialog_content = "Don't go wrecking my set or the props!",
  str_homestory_N23dianying_90030301_102_dialog_content = "I'm the sheriff around here, so if you need anything in the future, please come and find me.",
  str_homestory_N23dianying_90030301_103_dialog_content = "Anyway, I still have things to do, so I should be heading off. See you around.",
  str_homestory_N23dianying_90030301_104_dialog_content = "Hang on! What about the fight?",
  str_homestory_N23dianying_90030301_105_dialog_content = "Based on what I've just seen, I don't think you're capable of providing reliable intelligence.",
  str_homestory_N23dianying_90030301_106_dialog_content = "It's pretty despicable to pry into a lady's most private matters.",
  str_homestory_N23dianying_90030301_107_dialog_content = "I shall conduct my own research and adjudicate on my own. Goodbye.",
  str_homestory_N23dianying_90030301_108_dialog_content = "Why is this happening...",
  str_homestory_N23dianying_90030301_109_dialog_content = "That individual... were they really the sheriff?",
  str_homestory_N23dianying_90030301_110_option_content = "Apologize sincerely",
  str_homestory_N23dianying_90030301_110X1_dialog_content = "Don't just stand there! You're supposed to say your apology line now!",
  str_homestory_N23dianying_90030301_111_dialog_content = "Yes.",
  str_homestory_N23dianying_90030301_112_dialog_content = "I apologize for opening such an important personal letter without permission.",
  str_homestory_N23dianying_90030301_113_dialog_content = "It's okay. After all, it was a judgment call made at a critical moment for the benefit of the organization.",
  str_homestory_N23dianying_90030301_114_dialog_content = "Organization?",
  str_homestory_N23dianying_90030301_115_dialog_content = "The letter was written in code. It only appeared to be a love letter.",
  str_homestory_N23dianying_90030301_116_dialog_content = "While there was an inherent risk in opening it in front of the sheriff... It does appear we got away with it, as she wasn't the slight bit suspicious.",
  str_homestory_N23dianying_90030301_117_dialog_content = "And Night Impression lives up to its reputation as a trustworthy establishment.",
  str_homestory_N23dianying_90030301_118_dialog_content = "Wait, you mean you really are part of the gang?",
  str_homestory_N23dianying_90030301_119_dialog_content = "All of that was just made up on the spot?",
  str_homestory_N23dianying_90030301_120_dialog_content = "Yep.",
  str_homestory_N23dianying_90030301_121_dialog_content = "Wow! I didn't see that coming, Chubb!",
  str_homestory_N23dianying_90030301_122_dialog_content = "Anyway... Now that I've safely retrieved the letter, I should be going to my next stop on this mission.",
  str_homestory_N23dianying_90030301_123_dialog_content = "See you, Mr. Bartender.",
  str_homestory_N23dianying_90030301_124_dialog_content = "...",
  str_homestory_N23dianying_90030301_125_dialog_content = "What just happened?!",
  str_homestory_N23dianying_90030301_126_option_content = "Advise her to give up",
  str_homestory_N23dianying_90030301_126X1_dialog_content = "C'mon, what're you waiting for? This is the part where you're meant to try to talk her out of pursuing the relationship!",
  str_homestory_N23dianying_90030301_127_dialog_content = "Okay.",
  str_homestory_N23dianying_90030301_128_dialog_content = "By the way, Moon Maiden... There's something I need to tell you.",
  str_homestory_N23dianying_90030301_129_dialog_content = "It just so happens that the man you admire is a dangerous figure in the gang!",
  str_homestory_N23dianying_90030301_130_dialog_content = "...!",
  str_homestory_N23dianying_90030301_131_dialog_content = "The sheriff doesn't believe me, which is why she encouraged you to continue your emotional pursuit.",
  str_homestory_N23dianying_90030301_132_dialog_content = "But I advise you to just walk away. What if he isn't really the kind-hearted gentleman you think he is?",
  str_homestory_N23dianying_90030301_133_dialog_content = "... So you were trying to expose his true identity to the sheriff?",
  str_homestory_N23dianying_90030301_134_dialog_content = "Yes. Even though the sheriff doesn't believe me, I won't stop collecting evidence.",
  str_homestory_N23dianying_90030301_135_dialog_content = "...",
  str_homestory_N23dianying_90030301_136_dialog_content = "Moon Maiden?",
  str_homestory_N23dianying_90030301_137_dialog_content = "W-What are you doing?!",
  str_homestory_N23dianying_90030301_138_dialog_content = "I thought at first that the sheriff coerced you into reading the letter.",
  str_homestory_N23dianying_90030301_139_dialog_content = "Did that gentleman make a mistake...?",
  str_homestory_N23dianying_90030301_140_dialog_content = "W-What do you mean?",
  str_homestory_N23dianying_90030301_141_dialog_content = "The letter was written in code. It only appeared to be a love letter.",
  str_homestory_N23dianying_90030301_142_dialog_content = "Its purpose was to prevent just such a crisis.",
  str_homestory_N23dianying_90030301_143_dialog_content = "And I happen to be one of the participants in this clandestine mission.",
  str_homestory_N23dianying_90030301_144_dialog_content = "Wow! I didn't see that coming, Chubb!",
  str_homestory_N23dianying_90030301_145_dialog_content = "Hang on! So you're actually part of the gang?!",
  str_homestory_N23dianying_90030301_146_dialog_content = "Yeah... I really am sorry about this.",
  str_homestory_N23dianying_90030301_147_dialog_content = "But the security of the organization is paramount. So please, Mr. Bartender...",
  str_homestory_N23dianying_90030301_148_dialog_content = "Please keep your mouth shut forever.",
  str_homestory_N23dianying_90030301_149_dialog_content = "W-What are you doing?!",
  str_homestory_N23dianying_90030301_150_dialog_content = "Stay back!",
  str_homestory_N23dianying_90030301_151_option_content = "Question identity",
  str_homestory_N23dianying_90030301_151X1_dialog_content = "Have you forgotten your lines? You're supposed to be suspecting the other party's identity right about now!",
  str_homestory_N23dianying_90030301_152_dialog_content = "Sounds about right.",
  str_homestory_N23dianying_90030301_153_dialog_content = "What about the Moon Maiden?",
  str_homestory_N23dianying_90030301_154_dialog_content = "Yeah?",
  str_homestory_N23dianying_90030301_155_dialog_content = "Are you really just a spurned suitor?",
  str_homestory_N23dianying_90030301_156_dialog_content = "...",
  str_homestory_N23dianying_90030301_157_dialog_content = "It's not good to know too much, Mr. Bartender.",
  str_homestory_N23dianying_90030301_158_dialog_content = "But I'll be on my way, seeing as I have the letter.",
  str_homestory_N23dianying_90030301_159_dialog_content = "I knew something smelled fishy.",
  str_homestory_N23dianying_90030301_160_dialog_content = "I'm sure there's more than meets the eye in that letter. I'd better make a note of what it says while I still remember.",
  str_homestory_N23dianying_90030301_161_dialog_content = "I remember I put a pen and paper somewhere...",
  str_homestory_N23dianying_90030301_162_dialog_content = "You just couldn't leave it alone, could you?",
  str_homestory_N23dianying_90030301_163_dialog_content = "Y-You're still—",
  str_homestory_N23dianying_90030301_164_dialog_content = "Chu! Denouement! Chubb!",
  str_homestory_N23dianying_90030301_165_dialog_content = "Movie protagonists never check the rooms, Chubb!",
  str_homestory_N23dianying_90030301_166_dialog_content = "Why would that gentleman entrust such an important item to you?",
  str_homestory_N23dianying_90030301_167_dialog_content = "Unless it was all part of the plan?",
  str_homestory_N23dianying_90030301_168_dialog_content = "Regardless, to prevent any unexpected distractions from arising. Why don't we have a little stroll together, Mr. Bartender?",
  str_homestory_N23dianying_90030301_169_dialog_content = "Wait! What are you doing?!",
  str_homestory_N23dianying_90030301_170_dialog_content = "Stay back!",
  str_homestory_N23dianying_90030301_171_dialog_content = "You guys better not cross the line...",
  str_homestory_N23dianying_90030301_172_dialog_content = "Relax, Mr. Bartender. We won't make trouble for you.",
  str_homestory_N23dianying_90030301_172X1_dialog_content = "I'm good friends with your boss. He won't say anything if I take up a tiny bit of space here.",
  str_homestory_N23dianying_90030301_173_dialog_content = "We're good friends with the boss. I'm sure he won't mind.",
  str_homestory_N23dianying_90030301_174_dialog_content = "Er... B-Boss?",
  str_homestory_N23dianying_90030301_175_dialog_content = "... Fine. I got it.",
  str_homestory_N23dianying_90030301_176_dialog_content = "Damn you. Using my own boss to threaten me.",
  str_homestory_N23dianying_90030301_177_dialog_content = "This place will be nothing but a gang hangout at this rate.",
  str_homestory_N23dianying_90030301_178_dialog_content = "I'm sorry, this isn't what we agreed. There's no way I can accept.",
  str_homestory_N23dianying_90030301_179_dialog_content = "Can't you budge just a little bit in the name of all our years of friendship?",
  str_homestory_N23dianying_90030301_179X1_dialog_content = "You've been like a brother to me for all these years. Can't you give me just a bit of leeway?",
  str_homestory_N23dianying_90030301_180_dialog_content = "Business is business. All's fair in love and shopping malls, after all. They're battlefields, not places to make friends.",
  str_homestory_N23dianying_90030301_181_dialog_content = "If you were in my shoes, you'd do exactly the same.",
  str_homestory_N23dianying_90030301_182_dialog_content = "And you don't really think of me as a real friend, judging by the way you tampered with the contract last time.",
  str_homestory_N23dianying_90030301_183_dialog_content = "Ah, that was just a minor misunderstanding.",
  str_homestory_N23dianying_90030301_184_dialog_content = "Oh? Was the last time you interfered in our business a misunderstanding too?",
  str_homestory_N23dianying_90030301_185_dialog_content = "About that...",
  str_homestory_N23dianying_90030301_186_dialog_content = "Or the time before that, when you ran away the second the sheriff's people came?",
  str_homestory_N23dianying_90030301_187_dialog_content = "We were left alone to protect the boss's goods, but ended up paying such a high price and gaining absolutely nothing.",
  str_homestory_N23dianying_90030301_188_dialog_content = "...",
  str_homestory_N23dianying_90030301_189_dialog_content = "I really can't fathom why the higher ups are still willing to work with you.",
  str_homestory_N23dianying_90030301_190_dialog_content = "But as for me, you have no idea how much rage I've got pent up.",
  str_homestory_N23dianying_90030301_191_dialog_content = "And you still have the audacity to bring up our \"friendship\"?",
  str_homestory_N23dianying_90030301_192_dialog_content = "Oi, oi. If you're gonna fight, take it somewhere else.",
  str_homestory_N23dianying_90030301_193_dialog_content = "Is that how negotiations are supposed to go?!",
  str_homestory_N23dianying_90030301_194_dialog_content = "Oh, get off your high horse. Everyone's out for themselves. There's no right or wrong here.",
  str_homestory_N23dianying_90030301_195_dialog_content = "Haven't you secretly fed information about us to the Lionhead Gang in the past?",
  str_homestory_N23dianying_90030301_196_dialog_content = "We're just returning the favor. Restoring balance.",
  str_homestory_N23dianying_90030301_197_dialog_content = "Seems you hold a lot of grudges against us.",
  str_homestory_N23dianying_90030301_198_dialog_content = "So let's settle all our scores today, right here and right now.",
  str_homestory_N23dianying_90030301_199_dialog_content = "Fine by me. Don't even think of chickening out of admitting your mistakes.",
  str_homestory_N23dianying_90030301_200_dialog_content = "You two! Don't fight in here!",
  str_homestory_N23dianying_90030301_201_dialog_content = "Everyone just stop! Lay down your weapons!",
  str_homestory_N23dianying_90030301_202_dialog_content = "I just finished tidying the place up!",
  str_homestory_N23dianying_90030301_202X1_dialog_content = "I already said, that was a misunderstanding.",
  str_homestory_N23dianying_90030301_202X2_dialog_content = "We can't write in the same stiff way that you do.",
  str_homestory_N23dianying_90030301_202X3_dialog_content = "Oh? So the last time, when you robbed our merchandise, that was a misunderstanding too?",
  str_homestory_N23dianying_90030301_202X4_dialog_content = "That...",
  str_homestory_N23dianying_90030301_202X5_dialog_content = "The Shadowlord had me chase you across the Rediesel Desert for three days and nights.",
  str_homestory_N23dianying_90030301_202X6_dialog_content = "You just went all around, making a mess of everything before throwing it all back to me.",
  str_homestory_N23dianying_90030301_202X7_dialog_content = "That was a misunderstanding too, was it?",
  str_homestory_N23dianying_90030301_202X8_dialog_content = "Hey, aren't we making a movie?",
  str_homestory_N23dianying_90030301_202X9_dialog_content = "You're choosing now to bring up all this?",
  str_homestory_N23dianying_90030301_202X10_dialog_content = "Taki, Sinsa, please calm down!",
  str_homestory_N23dianying_90030301_202A1_dialog_content = "A fight! A fight!",
  str_homestory_N23dianying_90030301_202X11_dialog_content = "I'm sorry, but I don't think we can continue the shoot.",
  str_homestory_N23dianying_90030301_202X12_dialog_content = "I've been barely restraining my rage ever since I first saw your face on set.",
  str_homestory_N23dianying_90030301_202X13_dialog_content = "Fascinating. So what're you gonna do about it? Wanna throw fists?",
  str_homestory_N23dianying_90030301_202X14_dialog_content = "Bring it on.",
  str_homestory_N23dianying_90030301_202X15_dialog_content = "Get out if you're going to fight! Don't destroy the set or the props!",
  str_homestory_N23dianying_90030401_1_dialog_content = "Do you feel unwell, Your Majesty?",
  str_homestory_N23dianying_90030401_2_dialog_content = "Novio said that you haven't been eating well lately.",
  str_homestory_N23dianying_90030401_3_dialog_content = "They are worried, and have been trying to find new recipes for you.",
  str_homestory_N23dianying_90030401_4_dialog_content = "Sorry to have you all worried, Lola.",
  str_homestory_N23dianying_90030401_5_dialog_content = "I just don't have an appetite lately. There's no need for concern.",
  str_homestory_N23dianying_90030401_6_dialog_content = "Why not try some honey that I just collected? It's really sweet!",
  str_homestory_N23dianying_90030401_S6_dialog_content = "Or, if you don't want honey, we do have some new dishes.",
  str_homestory_N23dianying_90030401_7_dialog_content = "The honey is fine, but sugar really isn't good for the body.",
  str_homestory_N23dianying_90030401_8_dialog_content = "Huh? Who are you?",
  str_homestory_N23dianying_90030401_X8_dialog_content = "Sweetie pie, too much dessert and it ends up on your waist.",
  str_homestory_N23dianying_90030401_S8_dialog_content = "Your Majesty.",
  str_homestory_N23dianying_90030401_S9_dialog_content = "I'm Chef Eve, employed by Mr. Novio to make new dishes for you.",
  str_homestory_N23dianying_90030401_9_dialog_content = "My apologies, Your Majesty.",
  str_homestory_N23dianying_90030401_10_dialog_content = "I'm Chef Fleur, employed by Mr. Novio to make new dishes for you.",
  str_homestory_N23dianying_90030401_11_dialog_content = "I come from the Rediesel Desert, far away from Northland.",
  str_homestory_N23dianying_90030401_12_dialog_content = "I trust that I'll be able to bring you dishes you have never tasted before.",
  str_homestory_N23dianying_90030401_13_dialog_content = "See this Rediesel Brew? This is unlike any drink that you have here.",
  str_homestory_N23dianying_90030401_14_dialog_content = "I'm sure its unique mellow taste will excite your taste buds.",
  str_homestory_N23dianying_90030401_X14_dialog_content = "I'm the new chef, here at the behest of the cutie that calls himself Novio.",
  str_homestory_N23dianying_90030401_X15_dialog_content = "I'm from the Rediesel Desert and I've brought dishes you've never heard of with me.",
  str_homestory_N23dianying_90030401_X16_dialog_content = "This is the Winter Palace. We're capable of recreating every cuisine from any corner of the continent!",
  str_homestory_N23dianying_90030401_X17_dialog_content = "Oh I really doubt so, hun.",
  str_homestory_N23dianying_90030401_X18_dialog_content = "See this Rediesel Brew? This is unlike any drink that you have here.",
  str_homestory_N23dianying_90030401_X19_dialog_content = "It's a recipe exclusive to the Rediesel Desert, and it's passed down through heritage.",
  str_homestory_N23dianying_90030401_S14_dialog_content = "Not only that, it's far more stimulating than any other drink as well.",
  str_homestory_N23dianying_90030401_S15_dialog_content = "Last time, PlayerName only had a few gulps with my brother and...",
  str_homestory_N23dianying_90030401_S16_dialog_content = "W-Wait! That's not in the script, Eve!",
  str_homestory_N23dianying_90030401_S17_dialog_content = "Oh, right! What was my line again...?",
  str_homestory_N23dianying_90030401_S18_dialog_content = "Oh yeah. This is the Golden Four-Legged Dragon.",
  str_homestory_N23dianying_90030401_15_dialog_content = "It sure has a unique aroma.",
  str_homestory_N23dianying_90030401_16_dialog_content = "You're right! I can smell it from all the way over here!",
  str_homestory_N23dianying_90030401_X20_dialog_content = "This is the Golden Four-Legged Dragon.",
  str_homestory_N23dianying_90030401_17_dialog_content = "And this is the Golden Four-Legged Dragon.",
  str_homestory_N23dianying_90030401_18_dialog_content = "It's made from desert lizards that inhabit the deepest part of the desert. The meat is firm, the skin crispy.",
  str_homestory_N23dianying_90030401_19_dialog_content = "It's one of the Rediesel Desert's most famous dishes.",
  str_homestory_N23dianying_90030401_20_dialog_content = "Sounds good.",
  str_homestory_N23dianying_90030401_21_dialog_content = "Uhm... S-Sounds unique.",
  str_homestory_N23dianying_90030401_22_dialog_content = "As for the Desert Jewel, it's a true signature dish.",
  str_homestory_N23dianying_90030401_23_dialog_content = "It's made from the internal organs of sandworms, a creature unique to the Rediesel Desert.",
  str_homestory_N23dianying_90030401_24_dialog_content = "I-Internal organs of sandworms!?",
  str_homestory_N23dianying_90030401_25_dialog_content = "That's right. They are seasoned with rediesel and our own special seasoning, then roasted until the skin is slightly charred.",
  str_homestory_N23dianying_90030401_26_dialog_content = "It's aromatic, juicy, and highly nutritious—",
  str_homestory_N23dianying_90030401_27_dialog_content = "Stop, stop, stop! Enough!",
  str_homestory_N23dianying_90030401_28_dialog_content = "You Rediesel Wrench people really eat weird things!",
  str_homestory_N23dianying_90030401_29_dialog_content = "How can your stomach take it?",
  str_homestory_N23dianying_90030401_30_dialog_content = "Hush, Lola. We're trying to film a commercial here!",
  str_homestory_N23dianying_90030401_31_dialog_content = "S-Sorry...",
  str_homestory_N23dianying_90030401_32_dialog_content = "That sure sounds intriguing. I'll leave the cooking in your hands then.",
  str_homestory_N23dianying_90030401_X32_dialog_content = "That sure sounds intriguing. I'll leave the cooking in your hands then.",
  str_homestory_N23dianying_90030401_33_dialog_content = "My pleasure, Your Majesty.",
  str_homestory_N23dianying_90030401_X33_dialog_content = "Rediesel gourmet, the taste of which intrigues even the Queen of the North.",
  str_homestory_N23dianying_90030401_X34_dialog_content = "The Rediesel Foodfest is now available in the Rediesel Desert! For only four times a year!",
  str_homestory_N23dianying_90030401_X35_dialog_content = "You might even run into me there if you're lucky.",
  str_homestory_N23dianying_90030401_S33_dialog_content = "That sure sounds intriguing. I'll leave the cooking in your hands then.",
  str_homestory_N23dianying_90030401_S34_dialog_content = "My pleasure, Your Majesty!",
  str_homestory_N23dianying_90030401_34_dialog_content = "Rediesel gourmet, the taste of which enthuses even the Queen of the North.",
  str_homestory_N23dianying_90030401_35_dialog_content = "The Rediesel Foodfest is now available in the Rediesel Desert! For only four times a year!",
  str_homestory_N23dianying_90030401_36_dialog_content = "Interested? Contact Odd Jobs, our affiliate in Umbraton!",
  str_homestory_N23dianying_90030401_37_dialog_content = "Great group discounts and other amazing deals for the first 100 inquirers!",
  str_homestory_N23dianying_90030401_38_dialog_content = "Don't miss out!",
  str_homestory_N23dianying_90030501_1_dialog_content = "Are you okay, Miss Vice?",
  str_homestory_N23dianying_90030501_2_dialog_content = "Oh, I'm sorry. I blanked out for a moment there.",
  str_homestory_N23dianying_90030501_3_dialog_content = "What were you saying?",
  str_homestory_N23dianying_90030501_X1_dialog_content = "Director? Are you okay?",
  str_homestory_N23dianying_90030501_X2_dialog_content = "Sorry! I got distracted for a moment there.",
  str_homestory_N23dianying_90030501_X3_dialog_content = "What did you say?",
  str_homestory_N23dianying_90030501_S1_dialog_content = "Mr. Minos? Are you okay?",
  str_homestory_N23dianying_90030501_S2_dialog_content = "Oh, I'm sorry.",
  str_homestory_N23dianying_90030501_S3_dialog_content = "Can you repeat the question again?",
  str_homestory_N23dianying_90030501_S4_dialog_content = "It's okay. You look exhausted...",
  str_homestory_N23dianying_90030501_S5_dialog_content = "I wanted to ask you... You mentioned before that you regretted making this film.",
  str_homestory_N23dianying_90030501_4_dialog_content = "It's alright. Let me repeat myself.",
  str_homestory_N23dianying_90030501_5_dialog_content = "You said before that you regretted making this film.",
  str_homestory_N23dianying_90030501_6_dialog_content = "Why is that?",
  str_homestory_N23dianying_90030501_X4_dialog_content = "I-It's because we didn't realize until it was released that...",
  str_homestory_N23dianying_90030501_X5_dialog_content = "This film may be cursed.",
  str_homestory_N23dianying_90030501_S6_dialog_content = "Even though I don't personally subscribe to this kind of superstition...",
  str_homestory_N23dianying_90030501_S7_dialog_content = "But the crew, they all say this film is cursed.",
  str_homestory_N23dianying_90030501_7_dialog_content = "Because... it wasn't until it was released that we realized...",
  str_homestory_N23dianying_90030501_8_dialog_content = "This film may be cursed.",
  str_homestory_N23dianying_90030501_9_dialog_content = "Cursed?",
  str_homestory_N23dianying_90030501_10_dialog_content = "Yeah. Everyone who's seen the film or participated in its making...",
  str_homestory_N23dianying_90030501_11_dialog_content = "All experienced \"strange\" things.",
  str_homestory_N23dianying_90030501_12_dialog_content = "Hello, everyone. Today, I'm here to take you inside the Andersen Haunted House!",
  str_homestory_N23dianying_90030501_13_dialog_content = "It was originally owned by one Lady Astor.",
  str_homestory_N23dianying_90030501_14_dialog_content = "She'd scream whenever the candles went out.",
  str_homestory_N23dianying_90030501_15_dialog_content = "Eventually, she perished in a fire.",
  str_homestory_N23dianying_90030501_16_dialog_content = "The former owner's style was... really unique.",
  str_homestory_N23dianying_90030501_17_dialog_content = "These are just puppets, but they're kind of freaky to look at.",
  str_homestory_N23dianying_90030501_18_dialog_content = "<color=#e8d9bb>*Wind-up music box sounding*</color>",
  str_homestory_N23dianying_90030501_19_dialog_content = "\"One little, two little, three little puppets♪\"",
  str_homestory_N23dianying_90030501_20_dialog_content = "A-Ahhhhhh!!!! It's back!",
  str_homestory_N23dianying_90030501_X20_dialog_content = "I've been hearing this song sung by a female voice every night since that day!",
  str_homestory_N23dianying_90030501_X21_dialog_content = "And lately I've noticed that her voice seems to be getting closer and closer to me!",
  str_homestory_N23dianying_90030501_X22_dialog_content = "My fellow actors have been telling me the same thing.",
  str_homestory_N23dianying_90030501_S20_dialog_content = "Some actors and staff have been hearing her singing every night since that.",
  str_homestory_N23dianying_90030501_S21_dialog_content = "But I personally didn't hear a thing.",
  str_homestory_N23dianying_90030501_S22_dialog_content = "Could it be... they were hallucinating due to fatigue?",
  str_homestory_N23dianying_90030501_21_dialog_content = "I've been hearing that woman singing this song every night since that day!",
  str_homestory_N23dianying_90030501_22_dialog_content = "And I've noticed her voice seems to be getting closer and closer to me!",
  str_homestory_N23dianying_90030501_23_dialog_content = "Could it be that you're just too tired and hallucinating?",
  str_homestory_N23dianying_90030501_24_dialog_content = "I also watched the film before this interview.",
  str_homestory_N23dianying_90030501_25_dialog_content = "Yet nothing's happening to me.",
  str_homestory_N23dianying_90030501_26_dialog_content = "Could it just be a coincidence...?",
  str_homestory_N23dianying_90030501_27_dialog_content = "<color=#e8d9bb>*Footsteps approaching*</color>",
  str_homestory_N23dianying_90030501_X27_dialog_content = "What's that sound?",
  str_homestory_N23dianying_90030501_S27_dialog_content = "W-What is that sound?",
  str_homestory_N23dianying_90030501_S28_dialog_content = "The wind must've knocked something over...",
  str_homestory_N23dianying_90030501_28_dialog_content = "W-What was that...?",
  str_homestory_N23dianying_90030501_29_dialog_content = "I-I don't know. Sounds like something got knocked over.",
  str_homestory_N23dianying_90030501_30_dialog_content = "\"One little, two little, three little puppets ♪\"",
  str_homestory_N23dianying_90030501_S30_dialog_content = "A-Ahhhhhh!!!! T-That's the song!",
  str_homestory_N23dianying_90030501_S31_dialog_content = "This...",
  str_homestory_N23dianying_90030501_31_dialog_content = "Ahhhhhh! That's the song!",
  str_homestory_N23dianying_90030501_X31_dialog_content = "Whoaaa! That's it! That's the song!",
  str_homestory_N23dianying_90030501_32_dialog_content = "\"Four little, five little, six little puppets ♪\"",
  str_homestory_N23dianying_90030501_S32_dialog_content = "W-What's going on?",
  str_homestory_N23dianying_90030501_S33_dialog_content = "Let's not panic. Stay calm.",
  str_homestory_N23dianying_90030501_33_dialog_content = "W-What's going on?",
  str_homestory_N23dianying_90030501_34_dialog_content = "<color=#e8d9bb>Boom!</color>",
  str_homestory_N23dianying_90030501_35_dialog_content = "T-The light just went out!",
  str_homestory_N23dianying_90030501_36_dialog_content = "\"Seven little, eight little, nine little puppets ♪\"",
  str_homestory_N23dianying_90030501_X36_dialog_content = "Ugh. It's all my fault for making this film...",
  str_homestory_N23dianying_90030501_S36_dialog_content = "You, where's the main switch for the lights? Tell me now!",
  str_homestory_N23dianying_90030501_37_dialog_content = "It's all because of this movie... It must've been cursed...",
  str_homestory_N23dianying_90030501_38_dialog_content = "\"Nine little puppets—with only eight little heads ♪\"",
  str_homestory_N23dianying_90030501_39_dialog_content = "Heheh... Do you dare lay eyes upon me?",
  str_homestory_N23dianying_90030601_1_dialog_content = "Miss Siobhan, the preparations for the special operation are complete. We can take action at any time.",
  str_homestory_N23dianying_90030601_2_dialog_content = "Thank you! Now we're just waiting for the Grand Marshal so we can go do the indoor rehearsal of the conscription advertisement together...",
  str_homestory_N23dianying_90030601_X1_dialog_content = "Commander Vivian, the preparations for the special operation are complete. We can take action at any time.",
  str_homestory_N23dianying_90030601_X2_dialog_content = "Good job. The Grand Marshal should be here anytime. We'll start the indoor rehearsal of the conscription advertisement immediately once she arrives.",
  str_homestory_N23dianying_90030601_S1_dialog_content = "Commander Barton, the preparations for the special operation are complete. We can take action at any time.",
  str_homestory_N23dianying_90030601_S2_dialog_content = "Good job. The Grand Marshal will be here anytime. Then we can start the indoor rehearsal of the conscription advertisement immediately.",
  str_homestory_N23dianying_90030601_3_dialog_content = "Sorry to have kept you waiting, everyone.",
  str_homestory_N23dianying_90030601_4_dialog_content = "This is my first attempt at such innovative recruitment. Please keep your spirits up, and together, we'll show the world how valiant Illumina's soldier's are!",
  str_homestory_N23dianying_90030601_5_dialog_content = "Yes!",
  str_homestory_N23dianying_90030601_6_dialog_content = "I hope today shall be the day of your rebirth.",
  str_homestory_N23dianying_90030601_7_dialog_content = "Your past is in the past. What's important is who you will be today and tomorrow.",
  str_homestory_N23dianying_90030601_X7_dialog_content = "Do you choose to cower in the corner, or to step up and fight?",
  str_homestory_N23dianying_90030601_X8_dialog_content = "To live up to expectations, to bear the people's trust, and to answer their prayers?",
  str_homestory_N23dianying_90030601_X9_dialog_content = "To be bold and fearless for the ones we love.",
  str_homestory_N23dianying_90030601_S7_dialog_content = "Do you let Eclipsites destroy your homes, or do you rise and resist, vowing to rip their flesh apart even with just your teeth?",
  str_homestory_N23dianying_90030601_S8_dialog_content = "Remember what they've done to you, and let it fuel your anger.",
  str_homestory_N23dianying_90030601_S9_dialog_content = "For the future of all Aurorians, and the freedom of all our descendants.",
  str_homestory_N23dianying_90030601_8_dialog_content = "Will you give up on yourself and curl up where you are, or will you explore the unknown world with your partners?",
  str_homestory_N23dianying_90030601_9_dialog_content = "Explore the lost lands, overcome many obstacles, in order to obtain precious technology to protect the future of Aurorians.",
  str_homestory_N23dianying_90030601_10_dialog_content = "Your full commitment to your decision will mean experiencing exhaustion and pain down to your every bone and every nerve.",
  str_homestory_N23dianying_90030601_11_dialog_content = "You will roll around in the mud while being shouted at by your instructor. Your mind and body will be broken before being reforged.",
  str_homestory_N23dianying_90030601_12_dialog_content = "The training will seem merciless and brutal, but we all know respect is earned on the edge of the blade.",
  str_homestory_N23dianying_90030601_13_dialog_content = "The scars you earn from training will be proof of your determination.",
  str_homestory_N23dianying_90030601_14_dialog_content = "We keep vigil in the darkness and drive away any enemy that dares to intrude.",
  str_homestory_N23dianying_90030601_15_dialog_content = "Our ironclad will shall burn them away, whether they have sharp claws or massive bodies.",
  str_homestory_N23dianying_90030601_16_dialog_content = "Join us, and become the bone and flesh of the legions of Illumina.",
  str_homestory_N23dianying_90030601_17_dialog_content = "Fight alongside your noble brothers and sisters in arms, and embrace your new self.",
  str_homestory_N23dianying_90030601_18_dialog_content = "Stand with them and defend our right to live.",
  str_homestory_N23dianying_90030601_19_dialog_content = "Together, you are the great wall that stands between the barren battlefield and your warm hearth.",
  str_homestory_N23dianying_90030601_20_dialog_content = "I, Reinhardt, Grand Marshal of Illumina, command all legions of Illumina...",
  str_homestory_N23dianying_90030601_21_dialog_content = "to defend all Aurorians at all cost, until death.",
  str_homestory_N23dianying_90030601_22_dialog_content = "Splendor Illumina!",
  str_homestory_N23dianying_90030601_23_dialog_content = "Visit any Illumina recruitment centers for the chance to participate in a prize lottery!",
  str_homestory_N23dianying_90030601_24_dialog_content = "Prizes include: Gram's Seasoned Can, Siobhan Autographed Photo, Philyshy's Comfort Expedition Bed, and others!",
  str_homestory_N23dianying_90030601_25_dialog_content = "The first lucky hundred recruits will also receive a Cloud Island Hot Springs Experience Voucher!",
  str_homestory_N23dianying_90030601_26_dialog_content = "I see. Bringing up prizes to attract attention is a necessary approach.",
  str_homestory_N23dianying_90030601_27_dialog_content = "Shall we go to the hot springs together after filming the commercial?",
  str_homestory_N23dianying_90030601_X26_dialog_content = "Visit any Illumina recruitment centers for the chance to participate in a prize lottery!",
  str_homestory_N23dianying_90030601_X27_dialog_content = "Prizes include: Gram's Seasoned Can, The Other End Experience Voucher, Migard's Succulent Plants, and others!",
  str_homestory_N23dianying_90030601_X28_dialog_content = "The first lucky hundred recruits will also receive an Afternoon Delight Set!",
  str_homestory_N23dianying_90030601_X29_dialog_content = "We await seeing your names on the recruitment list!",
  str_homestory_N23dianying_90030601_S26_dialog_content = "Visit any Illumina recruitment centers for the chance to participate in a prize lottery!",
  str_homestory_N23dianying_90030601_S27_dialog_content = "Prizes include: Gram's Seasoned Can, Vida's Mine Detector Lollipop, Revy's Baseball Bat, and others!",
  str_homestory_N23dianying_90030601_S28_dialog_content = "The first lucky hundred recruits will also receive a Commander Barton Ship Companionship Voucher!",
  str_homestory_N23dianying_90030601_S29_dialog_content = "That's right! Seize this opportunity!"
}
return config
